//api.spotify.com/v1', '') : null;\n    }\n    if (!own.length) throw new Error('emptyradio');\n    // profil de styles de la playlist\n    const pArtists = [...aCount.entries()].sort((a, b) => b[1] - a[1]).slice(0, 40);\n    const infos = await this.many(pArtists.map(([aid]) => () => this.artist(aid)));\n    const gw = new Map();\n    infos.forEach((a, i) => { const c = pArtists[i] ? pArtists[i][1] : 1; for (const g of a.genres || []) gw.set(g, (gw.get(g) || 0) + c); });\n    let styles = [...gw.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8);\n    if (!styles.length) styles = [['drum and bass', 1], ['liquid funk', 1], ['jungle', 1]];\n    const wsum = styles.reduce((a, b) => a + b[1], 0), wOf = new Map(styles.map(([g, w]) => [g, w / wsum]));\n    // artistes candidats : ceux de la playlist (poids fort) + ceux des mêmes styles\n    const cand = new Map();\n    for (const a of infos) if (a && a.id) cand.set(a.id, { a, score: 1, mine: true });\n    const lists = await this.many(styles.flatMap(([g, w]) => (w / wsum > 0.18 ? [0, 10, 20] : w / wsum > 0.08 ? [0, 10] : [0]).map(o => () => this.searchArtists('genre:\"' + g + '\"', o))));\n    for (const list of lists) for (const a of list) {\n      if (cand.has(a.id)) continue;\n      const shared = (a.genres || []).filter(g => wOf.has(g));\n      if (!shared.length) continue;\n      const overlap = shared.reduce((x, g) => x + wOf.get(g), 0), purity = shared.length / Math.max(1, a.genres.length);\n      cand.set(a.id, { a, score: clamp(overlap * 2.2, 0.05, 1) * (0.5 + 0.5 * purity), mine: false });\n    }\n    const mine = [...cand.values()].filter(c => c.mine), others = [...cand.values()].filter(c => !c.mine).sort((x, y) => y.score - x.score).slice(0, 36);\n    const ownUris = new Set(own.map(t => t.uri)), ownNames = new Set(own.map(t => norm(t.name) + '|' + t.aid));\n    const jobs = [];\n    for (const c of mine.slice(0, 24).concat(others)) for (const o of c.mine ? [0, 10] : [0]) jobs.push(() => this.searchTracks('artist:\"' + c.a.name + '\"', o).then(ts => ts.filter(t => (t.artists || []).some(x => x.id === c.a.id)).map(t => { const it = trackItem(t, c.a.id); it.w = c.mine ? 1 : c.score; it.own = false; return it; })));\n    const found = (await this.many(jobs)).flat();\n    const seen = new Set(), names = new Set(ownNames), perArtist = new Map(), sim = [];\n    for (const it of found) {\n      const nk = norm(it.name) + '|' + it.aid;\n      if (ownUris.has(it.uri) || seen.has(it.uri) || names.has(nk)) continue;\n      const n = perArtist.get(it.aid) || 0; if (n >= 8) continue;\n      seen.add(it.uri); names.add(nk); perArtist.set(it.aid, n + 1); sim.push(it); this.byUri.set(it.uri, it);\n    }\n    const simF = this.instrumentalFirst(sim);\n    this.resolved = { at: Date.now(), name: this.radioName, own: own.length, sim: simF.length, artists: perArtist.size, styles: styles.map(x => x[0]) };\n    store.set('sp_resolved', this.resolved);\n    return own.concat(simF);\n  },\n  /* sans paroles d'abord : les morceaux visiblement chantés sont écartés tant qu'il reste assez d'instrumentaux */\n  instrumentalFirst(list) {\n    const clean = list.filter(t => t.v <= 0), maybe = list.filter(t => t.v > 0 && t.v < 3), voc = list.filter(t => t.v >= 3);\n    if (clean.length >= 30) return clean.concat(maybe.length > clean.length / 3 ? [] : maybe);\n    return clean.concat(maybe, clean.length + maybe.length >= 20 ? [] : voc);\n  },\n  async collect(path, pickTrack) {\n    const out = []; let p = path;\n    for (let i = 0; i < 20 && p; i++) {\n      const r = await this.api('GET', p);\n      for (const it of (r && r.items) || []) { const t = pickTrack(it); if (t && t.uri && /^spotify:track:/.test(t.uri) && t.is_local !== true) { const x = trackItem(t); this.byUri.set(x.uri, x); out.push(x); } }\n      p = r && r.next ? r.next.replace('https://api.spotify.com/v1', '') : null;\n    }\n    return out;\n  },\n  async loadPlaylists() {\n    try {\n      const r = await this.api('GET', '/me/playlists?limit=50');\n      this.playlists = ((r && r.items) || []).filter(p => p && p.id && (!this.uid || p.collaborative || (p.owner && p.owner.id === this.uid))).map(p => ({ id: p.id, name: p.name || 'Untitled', snap: p.snapshot_id || '' }));\n    } catch (e) { this.playlists = []; }\n    // la radio se base sur ta playlist « DRFT » tant que tu n'en choisis pas une autre\n    const cur = this.playlists.find(p => p.id === this.radioPl);\n    const pick = cur || this.playlists.find(p => norm(p.name) === 'drft') || this.playlists.find(p => /\\bdrft\\b/.test(norm(p.name)));\n    if (pick) this.setRadioBase(pick, true);\n    UI.renderSpotify(); UI.renderStations();\n  },\n  setRadioBase(pl, quiet) {\n    const changed = pl.id !== this.radioPl || (pl.snap && pl.snap !== this.radioSnap);\n    this.radioPl = pl.id; this.radioName = pl.name; if (pl.snap) this.radioSnap = pl.snap;\n    store.set('sp_radio_pl', this.radioPl); store.set('sp_radio_name', this.radioName); store.set('sp_radio_snap', this.radioSnap);\n    return changed;\n  },\n  feedKey(src) { src = src || this.source; return src === 'fm' ? 'fm|' + this.radioPl + '|' + this.radioSnap : src; },\n  async getPool(src) {\n    src = src || this.source;\n    const key = this.feedKey(src);\n    if (this.pool && this.poolKey === key) return;\n    if (this.building && this.building.key === key) return this.building.p;\n    const p = (async () => {\n      let items;\n      if (src.startsWith('pl:') && HOST && HOST.playlistItems) items = await HOST.playlistItems(src.slice(3), trackItem);\n      if (items) for (const it of items) this.byUri.set(it.uri, it);\n      else if (src.startsWith('pl:')) items = await this.collect('/playlists/' + src.slice(3) + '/items?limit=50', it => it.item || it.track);\n      else {\n        // la radio garde sa liste 12 h, pour ne pas tout rechercher à chaque ouverture\n        const c = store.get('sp_pool', null);\n        if (c && c.key === key && Date.now() - c.at < 12 * 3600000 && Array.isArray(c.items) && c.items.length) { items = c.items; for (const it of items) this.byUri.set(it.uri, it); }\n        else { if (!this.radioPl) throw new Error('noradio'); items = await this.buildFromPlaylist(this.radioPl); store.set('sp_pool', { key, at: Date.now(), items }); }\n      }\n      if (!items.length) throw new Error('empty');\n      this.pool = items; this.poolKey = key;\n    })().finally(() => { this.building = null; });\n    this.building = { key, p };\n    return p;\n  },\n  /* tirage : jamais un morceau entendu récemment, jamais deux fois le même artiste sur 4 morceaux.\n     Radio : un morceau de ta playlist, un morceau proche, et ainsi de suite (moitié / moitié) ;\n     parmi les morceaux proches, les artistes les plus proches sortent plus souvent. */\n  pickItems(n, first, avoid) {\n    const pool = this.pool || [], out = [];\n    if (first) out.push(this.byUri.get(first) || { uri: first, dur: 0, name: '', artist: '', aid: '' });\n    const block = new Set(avoid || []);\n    const half = this.source === 'fm' && pool.some(t => t.own) && pool.some(t => !t.own);\n    const order = list => { const k = list.map(t => [Math.pow(Math.random(), 1 / Math.max(0.05, t.w || 1)), t]); k.sort((a, b) => b[0] - a[0]); return k.map(x => x[1]); };\n    const lane = list => {\n      const recentN = Math.min(this.recent.length, Math.floor(list.length * 0.8)), rec = new Set(this.recent.slice(this.recent.length - recentN));\n      const ok = list.filter(t => !block.has(t.uri) && !rec.has(t.uri) && !out.some(o => o.uri === t.uri));\n      const more = list.filter(t => !block.has(t.uri) && rec.has(t.uri) && !out.some(o => o.uri === t.uri));\n      return order(ok).concat(shuffle(more));\n    };\n    const ownAll = half ? pool.filter(t => t.own) : [];\n    const lanes = half ? [lane(ownAll), lane(pool.filter(t => !t.own))] : [lane(pool)];\n    // ta playlist est plus courte que la radio : quand ses morceaux sont épuisés, ils reviennent,\n    // sauf les plus récents (60 % de la playlist), pour garder la moitié / moitié sans répétition rapprochée\n    const refillOwn = () => {\n      const hist = this.recent.concat(avoid ? [...avoid] : [], out.map(o => o.uri)), ownSet = new Set(ownAll.map(t => t.uri)), K = Math.ceil(ownAll.length * 0.6);\n      const last = new Set(); for (let i = hist.length - 1; i >= 0 && last.size < K; i--) if (ownSet.has(hist[i])) last.add(hist[i]);\n      return shuffle(ownAll.filter(t => !last.has(t.uri) && !out.slice(-K).some(o => o.uri === t.uri)));\n    };\n    let turn = half ? (Math.random() < 0.5 ? 0 : 1) : 0;\n    if (first && half) turn = (out[0] && out[0].own) ? 1 : 0;\n    let guard = 0;\n    while (out.length < n && guard++ < n * 4) {\n      if (half && !lanes[0].length) lanes[0] = refillOwn();\n      let L = lanes[turn % lanes.length]; if (!L.length) L = lanes.find(l => l.length);\n      if (!L) break;\n      const lastA = out.slice(-4).map(x => x.aid);\n      let i = L.findIndex(t => !t.aid || !lastA.includes(t.aid)); if (i < 0) i = 0;\n      const it = L.splice(i, 1)[0];\n      const K = it.own ? Math.ceil(ownAll.length * 0.6) * 2 : out.length;\n      if (!out.slice(-K).some(o => o.uri === it.uri)) out.push(it);\n      turn++;\n    }\n    return out;\n  },\n  async playUris(uris, pos) {\n    const body = { uris }; if (pos > 0) body.position_ms = Math.round(pos);\n    try { await this.api('PUT', '/me/player/play?device_id=' + encodeURIComponent(this.device), body); }\n    catch (e) { if (e.status !== 404) throw e; this.ready = false; await this.init(); await this.api('PUT', '/me/player/play?device_id=' + encodeURIComponent(this.device), body); }\n    this.sent = uris.slice(); this.sentPos = 0;\n  },\n  async playFresh(first) {\n    this.starting = true; this.guard(5000);\n    try {\n      await this.init();\n      if (this.source === 'fm' && !first) await Fm.tune();\n      else {\n        if (this.source === 'fm') Fm.leave();\n        await this.getPool();\n        await this.playUris(this.pickItems(40, first).map(x => x.uri));\n      }\n      if (!Fm.ducking) { this.fadeTok++; await this.player.setVolume(clamp(settings.vol * settings.vol, 0, 1)).catch(() => {}); }\n    } finally { this.starting = false; this.guard(2500); }\n  },\n  /* morceaux à ne pas rejouer tout de suite : les 200 derniers envoyés, mais jamais plus de 60 % de la liste,\n     sinon une playlist courte n'a plus rien à proposer et la boucle s'arrête après un tour */\n  recentSent() { const n = Math.min(200, Math.floor((this.pool || []).length * 0.6)); return new Set(n > 0 ? this.sent.slice(-n) : []); },\n  async topUp() {\n    if (this.topping) return;\n    this.topping = true;\n    try {\n      let list, fm = false;\n      if (this.source === 'fm' && Fm.sched) { await Fm.ensure(); list = Fm.takeNext(6); fm = list.length > 0; }\n      if (!list || !list.length) { await this.getPool(); list = this.pickItems(6, null, this.recentSent()).map(x => x.uri); }\n      const recentSent = new Set(this.sent.slice(-Math.max(4, Math.min(40, Math.floor((this.pool || []).filter(t => !t.own).length * 0.6)))));\n      for (const u of list) { const own = (this.byUri.get(u) || {}).own; if (!fm && !own && recentSent.has(u)) continue; await this.api('POST', '/me/player/queue?device_id=' + encodeURIComponent(this.device) + '&uri=' + encodeURIComponent(u)); this.sent.push(u); }\n    } catch (e) { /* on retentera au prochain changement */ }\n    this.topping = false;\n  },\n  async seek(ms) {\n    if (!this.player || !this.state) return;\n    Fm.leave(); this.guard(2000);\n    this.state = Object.assign({}, this.state, { position: Math.max(0, ms) }); this.stateAt = performance.now();\n    await this.player.seek(Math.max(0, Math.round(ms))).catch(() => {});\n  },\n  async fadeTo(v, ms) {\n    if (!this.player) return false;\n    const tok = ++this.fadeTok;\n    let from = v; try { from = await this.player.getVolume(); } catch (e) { /* ok */ }\n    const steps = Math.max(6, Math.min(80, Math.round(ms / 90)));\n    for (let i = 1; i <= steps; i++) {\n      if (tok !== this.fadeTok) return false;\n      const k = i / steps, e = v < from ? 1 - Math.pow(1 - k, 2) : k * k;\n      try { await this.player.setVolume(clamp(from + (v - from) * e, 0, 1)); } catch (er) { /* ok */ }\n      await waitMs(ms / steps);\n    }\n    return tok === this.fadeTok;\n  },\n  async pauseFx() {\n    if (!this.player) return;\n    // dans Spotify, le volume est celui du client : pas de fondu à zéro, il resterait muet après la pause\n    if (HOST) {\n      Fm.stopDuck(); this.guard(2500); this.fadeTok++;\n      await this.player.pause().catch(() => {});\n      await this.player.setVolume(clamp(settings.vol * settings.vol, 0, 1)).catch(() => {});\n      return;\n    }\n    Fm.stopDuck(); this.guard(2500);\n    const done = await this.fadeTo(0, 650);\n    if (done && !Radio.playing) { try { await this.player.pause(); } catch (e) { /* ok */ } }\n  },\n  async resumeFx() {\n    if (!this.player) return;\n    if (HOST) {\n      // Spotify joue autre chose (ou rien) : on relance la radio au lieu de reprendre ce qu'il jouait\n      if (!this.state) { await this.playFresh().catch(e => Radio.spFail(e)); return; }\n      this.guard(2500); this.fadeTok++;\n      await this.player.setVolume(clamp(settings.vol * settings.vol, 0, 1)).catch(() => {});\n      await this.player.resume().catch(() => {});\n      return;\n    }\n    this.guard(2500); this.fadeTok++;\n    try { await this.player.setVolume(0.0001); await this.player.resume(); } catch (e) { /* ok */ }\n    await this.fadeTo(clamp(settings.vol * settings.vol, 0, 1), 450);\n  },\n  setVolume(v) { if (this.player && Radio.cur === SpPlayer && Radio.playing && !sleep.fading && !Fm.ducking) { this.fadeTok++; this.player.setVolume(clamp(v * v, 0, 1)).catch(() => {}); } }\n};\n\n/* =====================================================================\n   DRFT FM : une vraie radio pour toi seul. La grille tourne avec l'horloge,\n   même quand DRFT est fermé : en revenant, tu reprends au milieu du morceau en cours.\n   ===================================================================== */\nconst SHOWS = [\n  { h: 2, name: 'LAST TOUGE', jp: '最終峠' }, { h: 6, name: 'MORNING RUN', jp: '朝練' }, { h: 10, name: 'MIDDAY CRUISE', jp: '昼下がり' },\n  { h: 14, name: 'AFTERNOON LAPS', jp: '周回' }, { h: 18, name: 'NIGHT DRIVE', jp: '夜走' }, { h: 22, name: 'MIDNIGHT WANGAN', jp: '湾岸' }\n];\nfunction showAt(ts) { const h = new Date(ts).getHours(); let s = SHOWS[SHOWS.length - 1]; for (const x of SHOWS) if (h >= x.h) s = x; return s; }\n\nconst Fm = {\n  live: false, sched: store.get('fm_sched2', null), sinceJingle: 0, ducking: false, lastShow: null, lastRetune: 0,\n  active() { return Radio.cur === SpPlayer && Sp.source === 'fm'; },\n  save() { store.set('fm_sched2', this.sched); },\n  total(s) { return s.items.reduce((a, b) => a + (b.dur || 210000), 0); },\n  async ensure() {\n    const now = Date.now(), key = Sp.feedKey('fm');\n    let s = this.sched;\n    const valid = s && s.key === key && Array.isArray(s.items) && s.items.length && now >= s.epoch && now < s.epoch + this.total(s) - 60000;\n    if (!valid) {\n      await Sp.getPool('fm');\n      const items = Sp.pickItems(60).filter(x => x.dur > 0);\n      if (!items.length) throw new Error('empty');\n      // on arrive au milieu d'un morceau, comme quand on allume une radio\n      s = { key, epoch: now - Math.floor(items[0].dur * (0.15 + Math.random() * 0.5)), items };\n      this.sched = s; this.save();\n    } else if (s.epoch + this.total(s) - now < 90 * 60000) {\n      await Sp.getPool('fm');\n      const more = Sp.pickItems(40, null, new Set(s.items.map(x => x.uri))).filter(x => x.dur > 0);\n      // on garde les 6 dernières heures de grille pour ne pas grossir sans fin\n      let cut = 0; const keepFrom = now - 6 * 3600000; let acc = s.epoch;\n      while (cut < s.items.length - 1 && acc + s.items[cut].dur < keepFrom) { acc += s.items[cut].dur; cut++; }\n      s = { key, epoch: acc, items: s.items.slice(cut).concat(more) };\n      this.schedEnd = Math.max(-1, this.schedEnd - cut);\n      this.sched = s; this.save();\n    }\n    for (const it of s.items) if (!Sp.byUri.has(it.uri)) Sp.byUri.set(it.uri, it);\n    return s;\n  },\n  at(ts) {\n    const s = this.sched; if (!s) return null;\n    let t = ts - s.epoch; if (t < 0) return null;\n    for (let i = 0; i < s.items.length; i++) { const d = s.items[i].dur || 210000; if (t < d) return { i, off: t, item: s.items[i] }; t -= d; }\n    return null;\n  },\n  async tune(quiet) {\n    const s = await this.ensure();\n    const p = this.at(Date.now());\n    if (!p) throw new Error('empty');\n    this.live = true; this.lastRetune = Date.now();\n    await Sp.playUris(s.items.slice(p.i, p.i + 30).map(x => x.uri), p.off);\n    this.schedEnd = Math.min(s.items.length - 1, p.i + 29);\n    UI.renderLive();\n    if (!quiet) this.ident(true);\n  },\n  /* la suite de la grille après le dernier morceau envoyé à Spotify */\n  schedEnd: -1,\n  takeNext(n) {\n    const s = this.sched; if (!s || this.schedEnd < 0) return [];\n    const out = s.items.slice(this.schedEnd + 1, this.schedEnd + 1 + n).map(x => x.uri);\n    this.schedEnd += out.length;\n    return out;\n  },\n  leave() { if (this.live) { this.live = false; UI.renderLive(); } },\n  async goLive() {\n    if (Radio.cur !== SpPlayer) return;\n    Sp.guard(5000); Sp.starting = true;\n    try { await this.tune(); if (!Radio.playing) { Radio.playing = true; UI.syncPlay(); } if (!this.ducking) { Sp.fadeTok++; await Sp.player.setVolume(clamp(settings.vol * settings.vol, 0, 1)).catch(() => {}); } }\n    catch (e) { Radio.spFail(e); }\n    finally { Sp.starting = false; Sp.guard(2500); }\n  },\n  /* à chaque nouveau morceau en direct : on vérifie qu'on colle à la grille, et parfois un jingle */\n  onTrack(tr, pos) {\n    if (!this.active()) return;\n    this.sinceJingle++;\n    if (this.live) {\n      // la grille « respire » : on recale l'heure de départ sur le morceau réellement joué\n      const now = Date.now(), p = this.at(now), s = this.sched;\n      const key = norm(tr.name) + '|' + norm(tr.artists && tr.artists[0] && tr.artists[0].name);\n      const same = it => it && (it.uri === tr.uri || norm(it.name) + '|' + norm(it.artist.split(', ')[0]) === key);\n      let j = -1;\n      if (p) for (const d of [0, 1, -1, 2]) if (same(s.items[p.i + d])) { j = p.i + d; break; }\n      let ok = j >= 0, shift = 0;\n      if (ok) { let start = s.epoch; for (let i = 0; i < j; i++) start += s.items[i].dur || 210000; shift = (now - pos) - start; ok = Math.abs(shift) <= 45000; }\n      if (ok) { s.epoch += shift; this.save(); }\n      // décalé : on se réaccorde, mais jamais plus d'une fois toutes les 2 minutes (sinon on reste hors direct)\n      else if (now - this.lastRetune > 120000) { this.goLive(); return; }\n      else this.leave();\n    }\n    const show = showAt(Date.now());\n    if (show !== this.lastShow || this.sinceJingle >= 3) this.ident(false);\n  },\n  ident(first) {\n    this.sinceJingle = 0; this.lastShow = showAt(Date.now());\n    Jingle.play();\n    this.duck();\n  },\n  duckTok: 0,\n  async duck() {\n    if (!Sp.player) return;\n    const tok = ++this.duckTok, alive = () => tok === this.duckTok && Radio.playing && Radio.cur === SpPlayer;\n    this.ducking = true;\n    await Sp.fadeTo(clamp(settings.vol * settings.vol, 0, 1) * 0.3, 250);\n    await waitMs(1700);\n    if (alive()) await Sp.fadeTo(clamp(settings.vol * settings.vol, 0, 1), 900);\n    if (tok === this.duckTok) this.ducking = false;\n  },\n  stopDuck() { this.duckTok++; this.ducking = false; }\n};\n\n/* jingle DRFT FM : souffle qui monte, trois notes de cloche, une basse ronde (synthèse, 2 s) */\nconst Jingle = {\n  play() {\n    if (!Radio.ensureCtx()) return;\n    const c = Radio.ctx, k = Radio.kit;\n    c.resume().catch(() => {});\n    if (Radio.cur === SpPlayer) { const n = c.currentTime; Radio.hold(k.dry.gain, n); k.dry.gain.setValueAtTime(1, n); Radio.hold(k.pauseLP.frequency, n); k.pauseLP.frequency.setValueAtTime(20000, n); }\n    const t = c.currentTime + 0.05, out = mkGain(c, 0.9); out.connect(k.post);\n    // souffle\n    const len = Math.floor(c.sampleRate * 1.2), nb = c.createBuffer(1, len, c.sampleRate), d = nb.getChannelData(0);\n    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;\n    const ns = c.createBufferSource(); ns.buffer = nb;\n    const bp = mkFilt(c, 'bandpass', 500, 2.2), ng = mkGain(c, 0);\n    bp.frequency.setValueAtTime(400, t); bp.frequency.exponentialRampToValueAtTime(5200, t + 0.75);\n    ng.gain.setValueAtTime(0, t); ng.gain.linearRampToValueAtTime(0.22, t + 0.6); ng.gain.linearRampToValueAtTime(0, t + 0.95);\n    ns.connect(bp); bp.connect(ng); ng.connect(out); ns.start(t); ns.stop(t + 1.2);\n    // cloches FM\n    [[880, 0.62], [1318.5, 0.74], [1975.5, 0.86]].forEach(([f, at]) => {\n      const st = t + at, car = c.createOscillator(), mod = c.createOscillator(), mg = mkGain(c, 0), g = mkGain(c, 0);\n      car.frequency.value = f; mod.frequency.value = f * 3.5;\n      mg.gain.setValueAtTime(f * 1.6, st); mg.gain.exponentialRampToValueAtTime(f * 0.02, st + 1.1);\n      g.gain.setValueAtTime(0, st); g.gain.linearRampToValueAtTime(0.16, st + 0.01); g.gain.exponentialRampToValueAtTime(0.0008, st + 1.3);\n      mod.connect(mg); mg.connect(car.frequency); car.connect(g); g.connect(out);\n      car.start(st); mod.start(st); car.stop(st + 1.35); mod.stop(st + 1.35);\n    });\n    // basse\n    const sub = c.createOscillator(), sg = mkGain(c, 0), st2 = t + 0.62;\n    sub.frequency.setValueAtTime(110, st2); sub.frequency.exponentialRampToValueAtTime(55, st2 + 0.25);\n    sg.gain.setValueAtTime(0, st2); sg.gain.linearRampToValueAtTime(0.3, st2 + 0.015); sg.gain.exponentialRampToValueAtTime(0.001, st2 + 0.6);\n    sub.connect(sg); sg.connect(out); sub.start(st2); sub.stop(st2 + 0.65);\n    setTimeout(() => { try { out.disconnect(); } catch (e) { /* ok */ } }, 3000);\n  }\n};\n\n/* objet « lecteur » vu par la radio et l'interface pendant l'écoute Spotify */\nconst SpPlayer = {\n  kind: 'spotify', tr: null, t0: 0, killed: false, endTime: Infinity,\n  posInfo() {\n    const s = Sp.state;\n    if (!s || !this.tr) return { el: 0, dur: 0, section: 'Loading' };\n    const dur = (s.duration || 0) / 1000;\n    const el = (s.position + (s.paused ? 0 : performance.now() - Sp.stateAt)) / 1000;\n    return { el: clamp(el, 0, dur || el), dur, section: 'Track' };\n  },\n  kill() { Sp.fadeTok++; Fm.leave(); if (Sp.player) Sp.player.pause().catch(() => {}); }\n};\n\n/* =====================================================================\n   RADIO : Spotify (ton compte) ou ta bibliothèque, enchaînements, pause en fondu\n   ===================================================================== */\nconst Radio = {\n  ctx: null, kit: null, playing: false, players: [], cur: null, history: [], count: 0, seq: 0,\n  station: 'spotify', files: [], fileQueue: [], lastFile: null, failStreak: 0, worker: null, prep: null,\n  pauseTok: 0, pauseTimer: 0, spNoHist: false,\n  ensureCtx() {\n    if (this.ctx) return true;\n    const AC = window.AudioContext || window.webkitAudioContext;\n    if (!AC) return false;\n    this.ctx = new AC({ latencyHint: 'playback' });\n    this.kit = makeKit(this.ctx);\n    this.setVolume(settings.vol);\n    this.startClock();\n    return true;\n  },\n  async start() {\n    this.ensureCtx();\n    if (this.station === 'local' && !this.files.some(f => !f.bad)) { this.station = 'spotify'; if (settings.src === 'local') setSrc('radio'); }\n    if (this.station === 'spotify') return this.spStart();\n    if (!this.ensureCtx()) { UI.toast('BROWSER NOT SUPPORTED (WEB AUDIO)'); return false; }\n    if (!this.playing && this.cur) { await this.resumeFx(); return true; }\n    this.openGate();\n    this.playing = true; UI.syncPlay();\n    if (!this.cur) this.playNext();\n    return true;\n  },\n  /* remet la sortie locale à plein (après une pause ou un passage par Spotify) */\n  openGate() {\n    const c = this.ctx, k = this.kit; if (!c) return;\n    this.pauseTok++; clearTimeout(this.pauseTimer);\n    c.resume().catch(() => {});\n    const now = c.currentTime;\n    this.hold(k.dry.gain, now); k.dry.gain.setValueAtTime(1, now);\n    this.hold(k.pauseLP.frequency, now); k.pauseLP.frequency.setValueAtTime(20000, now);\n  },\n  /* ---------- Spotify ---------- */\n  async spStart(first) {\n    if (!Sp.connected()) {\n      UI.toast('CONNECT YOUR SPOTIFY FIRST · ONE-TIME SETUP');\n      setDrawer(true, 'music'); UI.focusSpotify();\n      return false;\n    }\n    if (this.cur === SpPlayer && !first) { if (!this.playing) await this.resumeFx(); return true; }\n    const tok = ++this.seq;\n    if (this.cur && this.cur !== SpPlayer) { if (this.ctx) { if (!this.playing) this.openGate(); this.cur.kill(this.ctx.currentTime); } this.cur = null; }\n    this.dropPrep();\n    this.cur = SpPlayer; SpPlayer.tr = null; Sp.lastUri = null;\n    this.playing = true; UI.syncPlay(); UI.loading();\n    UI.showTrack({ kind: 'spotify', title: Sp.source === 'fm' ? 'DRFT FM' : (Sp.plName || 'PLAYLIST'), artist: 'Tuning in…' });\n    try {\n      if (Sp.source === 'fm' && !Sp.radioPl && !Sp.playlists) await Sp.loadPlaylists();\n      await Sp.playFresh(first);\n      if (tok !== this.seq) return true;\n      return true;\n    } catch (e) {\n      if (tok === this.seq) this.spFail(e);\n      return false;\n    }\n  },\n  spFail(e) {\n    const st = e && e.status, m = e && e.message;\n    let msg = 'SPOTIFY ERROR · ' + String(m || 'UNKNOWN').toUpperCase().slice(0, 60);\n    if (m === 'sdk') msg = 'SPOTIFY PLAYER BLOCKED · TURN OFF THE AD BLOCKER FOR THIS SITE';\n    else if (m === 'device' || m === 'connect') msg = 'SPOTIFY PLAYER DIDN\\'T START · TRY AGAIN';\n    else if (m === 'empty') msg = 'NOTHING FOUND IN THIS PLAYLIST';\n    else if (m === 'emptyradio') msg = 'THE RADIO PLAYLIST IS EMPTY · ADD TRACKS TO IT IN SPOTIFY';\n    else if (m === 'noradio') { msg = 'CHOOSE THE PLAYLIST THE RADIO IS BASED ON'; setDrawer(true, 'music'); }\n    else if (st === 401) msg = 'SPOTIFY SESSION ENDED · RECONNECT IN THE MENU';\n    else if (st === 403) msg = 'SPOTIFY REFUSED · CHECK PREMIUM AND YOUR APP\\'S USER MANAGEMENT';\n    else if (st === 404) msg = 'SPOTIFY DEVICE LOST · PRESS PLAY AGAIN';\n    UI.toast(msg);\n    if (this.cur === SpPlayer) { this.cur = null; this.playing = false; UI.syncPlay(); UI.showTrack({ kind: 'spotify', title: 'DRFT', artist: 'Spotify' }); }\n  },\n  spTrackChanged(tr, uri) {\n    uri = uri || tr.uri;\n    const id = uri.split(':').pop();\n    const imgs = (tr.album && tr.album.images) || [];\n    const spec = { kind: 'spotify', id: 'sp-' + id, uri, title: tr.name || 'Untitled', artist: (tr.artists || []).map(a => a.name).join(', ') || 'Unknown',\n      link: 'https://open.spotify.com/track/' + id, img: imgs.length ? imgs[imgs.length - 1].url : '' };\n    SpPlayer.tr = spec;\n    if (this.cur !== SpPlayer) return;\n    this.register(spec, this.spNoHist ? { noHistory: true } : null);\n    this.spNoHist = false;\n  },\n  /* ---------- bibliothèque locale ---------- */\n  startClock() {\n    const tick = () => this.tick();\n    try {\n      const w = new Worker(URL.createObjectURL(new Blob(['setInterval(function(){postMessage(0)},40);'], { type: 'text/javascript' })));\n      w.onmessage = tick; this.worker = w;\n    } catch (e) { /* minuteur de secours ci-dessous */ }\n    setInterval(tick, 80);\n  },\n  fileSpec(item) {\n    const m = item.name.match(/\\.([a-z0-9]+)$/i);\n    return { kind: 'file', item, title: item.title, artist: item.artist, ext: m ? m[1].toUpperCase() : 'File', id: 'file-' + item.id };\n  },\n  nextFileSpec() {\n    const good = this.files.filter(f => !f.bad);\n    if (!good.length) return null;\n    if (!this.fileQueue.length) {\n      this.fileQueue = shuffle(good.slice());\n      if (this.fileQueue.length > 1 && this.fileQueue[this.fileQueue.length - 1] === this.lastFile) this.fileQueue.unshift(this.fileQueue.pop());\n    }\n    let item = this.fileQueue.pop();\n    while (item && (!this.files.includes(item) || item.bad) && this.fileQueue.length) item = this.fileQueue.pop();\n    if (!item || !this.files.includes(item) || item.bad) item = good[Math.floor(Math.random() * good.length)];\n    this.lastFile = item;\n    return this.fileSpec(item);\n  },\n  playNext() {\n    ++this.seq;\n    UI.loading();\n    const spec = this.nextFileSpec();\n    if (!spec) { this.noSource(); return; }\n    this.begin(spec);\n  },\n  noSource() {\n    UI.toast(Sp.connected() ? 'NO WAVS · BACK TO THE RADIO' : 'ADD YOUR WAVS FIRST');\n    this.cur = null; this.playing = false; UI.syncPlay();\n    if (Sp.connected()) { setSrc('radio'); this.setStation('spotify'); }\n  },\n  register(spec, opts) {\n    this.count++; spec.num = this.count;\n    if (!opts || !opts.noHistory) { this.history.push(spec); if (this.history.length > 80) this.history.shift(); UI.renderHistory(); }\n  },\n  adoptAt(p, at, fade, opts) {\n    this.register(p.tr, opts);\n    this.players.push(p); this.cur = p;\n    p.onEnd = q => this.ended(q);\n    p.start(at, fade);\n    this.failStreak = 0;\n  },\n  async begin(spec, opts = {}) {\n    const p = new FilePlayer(this.kit, spec);\n    this.cur = p; UI.showTrack(spec);\n    let ok = false;\n    try { ok = (await p.load()) !== false; } catch (e) { ok = false; }\n    if (this.cur !== p) { p.dispose(); return; }\n    if (!ok) {\n      p.dispose(); if (spec.item) spec.item.bad = true;\n      this.failStreak++;\n      if (this.failStreak >= 8) { this.failStreak = 0; this.noSource(); return; }\n      UI.toast('SKIPPED · ' + spec.title.toUpperCase());\n      this.playNext();\n      return;\n    }\n    this.adoptAt(p, this.ctx.currentTime + 0.05, 0, opts);\n  },\n  ended(p) {\n    if (this.cur !== p || !this.playing) return;\n    const now = this.ctx.currentTime, n = this.prep;\n    if (n && n.ok) { this.prep = null; this.adoptAt(n, now + 0.03, 0); return; }\n    this.dropPrep(); this.playNext();\n  },\n  dropPrep() { const n = this.prep; this.prep = null; if (n) n.dispose(); },\n  prepNext() {\n    if (this.prep || this.station !== 'local') return;\n    const spec = this.nextFileSpec(); if (!spec) return;\n    const n = new FilePlayer(this.kit, spec); this.prep = n; n.load().catch(() => {});\n  },\n  xfade(p) { const x = +settings.xfade || 0; return Math.min(x, p.dur ? p.dur / 3 : x); },\n  tick() {\n    const c = this.ctx;\n    if (!c || c.state !== 'running' || !this.playing) return;\n    const now = c.currentTime, p = this.cur;\n    if (this.prep && this.prep.failed) {\n      const bad = this.prep; this.prep = null;\n      bad.dispose(); bad.tr.item.bad = true; UI.toast('UNREADABLE, SKIPPED: ' + bad.tr.title);\n    }\n    if (p && p.kind === 'file' && p.state === 'playing' && !p.handedOff && !p.killed && !p.fading && !p.held) {\n      if (!this.prep) this.prepNext();\n      const n = this.prep, xf = this.xfade(p);\n      if (n && n.ok && p.endTime - now <= xf + 0.2) {\n        p.handedOff = true; this.prep = null;\n        const at = Math.max(now + 0.05, p.endTime - xf);\n        if (xf > 0.05) p.fadeOut(at, xf);\n        this.adoptAt(n, at, xf);\n      }\n    }\n    this.players = this.players.filter(q => {\n      if (q !== this.cur && q.endTime + 4 < now) { q.dispose(); return false; }\n      return true;\n    });\n  },\n  onAir() {\n    if (this.cur === SpPlayer) return SpPlayer;\n    if (!this.ctx) return null;\n    const now = this.ctx.currentTime;\n    let best = null;\n    for (const p of this.players) if (p.t0 <= now + 0.02 && !(p.killed && p.endTime < now) && (!best || p.t0 >= best.t0)) best = p;\n    return best || this.cur;\n  },\n  async toggle() {\n    if (!this.cur) { await this.start(); return; }\n    if (this.playing) this.pause(); else await this.resumeFx();\n  },\n  hold(p, now) { if (p.cancelAndHoldAtTime) p.cancelAndHoldAtTime(now); else { p.cancelScheduledValues(now); p.setValueAtTime(p.value, now); } },\n  /* pause : le son se referme comme un filtre et s'éteint en douceur (0,7 s), puis tout se fige */\n  pause() {\n    if (!this.playing) return;\n    if (this.cur === SpPlayer) { this.playing = false; Fm.leave(); UI.syncPlay(); Sp.pauseFx(); return; }\n    if (!this.ctx) return;\n    this.playing = false; UI.syncPlay();\n    const c = this.ctx, k = this.kit, now = c.currentTime, tok = ++this.pauseTok, D = 0.7;\n    this.hold(k.dry.gain, now); k.dry.gain.setTargetAtTime(0, now, D / 4);\n    this.hold(k.pauseLP.frequency, now); k.pauseLP.frequency.exponentialRampToValueAtTime(320, now + D);\n    for (const q of this.players) if (q.holdAt) q.holdAt(now, D + 0.05);\n    clearTimeout(this.pauseTimer);\n    this.pauseTimer = setTimeout(() => { if (tok === this.pauseTok && !this.playing) c.suspend().catch(() => {}); }, (D + 0.2) * 1000);\n  },\n  async resumeFx() {\n    if (this.cur === SpPlayer) { this.playing = true; UI.syncPlay(); await Sp.resumeFx(); return; }\n    if (!this.ctx) return;\n    this.pauseTok++; clearTimeout(this.pauseTimer);\n    try { await this.ctx.resume(); } catch (e) { /* ok */ }\n    const k = this.kit, now = this.ctx.currentTime;\n    for (const q of this.players) if (q.resumeAt) q.resumeAt(now + 0.05);\n    this.hold(k.dry.gain, now); k.dry.gain.setTargetAtTime(1, now + 0.05, 0.1);\n    this.hold(k.pauseLP.frequency, now); k.pauseLP.frequency.setValueAtTime(Math.max(320, Math.min(k.pauseLP.frequency.value || 320, 20000)), now);\n    k.pauseLP.frequency.exponentialRampToValueAtTime(20000, now + 0.45);\n    if (!sleep.end) this.hold(k.sleep.gain, now), k.sleep.gain.setValueAtTime(1, now);\n    this.playing = true; UI.syncPlay();\n  },\n  async next() {\n    if (!this.cur) { await this.start(); return; }\n    if (this.cur === SpPlayer) {\n      if (!this.playing) { this.playing = true; UI.syncPlay(); }\n      const s = Sp.state, more = s && s.track_window && (s.track_window.next_tracks || []).length;\n      Fm.leave(); Sp.guard(2500);\n      if (more && Sp.player) { Sp.fadeTok++; await Sp.player.nextTrack().catch(() => {}); if (s && s.paused) Sp.player.resume().catch(() => {}); Sp.player.setVolume(clamp(settings.vol * settings.vol, 0, 1)).catch(() => {}); }\n      else {\n        const after = Sp.source === 'fm' ? Fm.takeNext(30) : [];\n        if (after.length) { Sp.playUris(after).catch(e => this.spFail(e)); }\n        else Sp.getPool().then(() => Sp.playUris(Sp.pickItems(40, null, Sp.recentSent()).map(x => x.uri))).catch(e => this.spFail(e));\n      }\n      return;\n    }\n    if (!this.ctx) { await this.start(); return; }\n    if (!this.playing) await this.resumeFx();\n    const now = this.ctx.currentTime, n = this.prep;\n    if (this.cur) this.cur.kill(now);\n    if (n && n.ok) { this.prep = null; this.adoptAt(n, now + 0.06, 0.06); return; }\n    this.dropPrep();\n    this.playNext();\n  },\n  async playSpec(spec, noHistory) {\n    if (spec.kind === 'spotify') {\n      if (settings.src === 'local') setSrc('radio');\n      if (this.station !== 'spotify') { this.station = 'spotify'; settings.station = 'spotify'; saveSettings(); UI.renderStations(); }\n      await this.spStart(spec.uri);\n      return;\n    }\n    if (this.cur === SpPlayer) { SpPlayer.kill(); this.cur = null; }\n    if (this.station !== 'local') { this.station = 'local'; setSrc('local'); UI.renderStations(); UI.renderSpotify(); }\n    if (!this.ensureCtx()) return;\n    if (!this.playing) { if (this.cur) await this.resumeFx(); else this.openGate(); }\n    this.playing = true; UI.syncPlay();\n    const now = this.ctx.currentTime;\n    this.seq++;\n    if (this.cur) this.cur.kill(now);\n    this.begin(spec, { noHistory });\n  },\n  async prev() {\n    if (this.cur === SpPlayer) {\n      const s = Sp.state; if (!s || !Sp.player) return;\n      Fm.leave(); Sp.guard(2500);\n      if (s.position > 4000 || !(s.track_window.previous_tracks || []).length) await Sp.player.seek(0).catch(() => {});\n      else await Sp.player.previousTrack().catch(() => {});\n      if (!this.playing) this.resumeFx();\n      return;\n    }\n    if (!this.ctx) return;\n    const loc = this.history.filter(h => h.kind === 'file');\n    if (this.history.length < 2 || this.history[this.history.length - 2].kind !== 'file') { UI.toast('NO PREVIOUS TRACK'); return; }\n    this.history.pop();\n    const last = this.history[this.history.length - 1];\n    if (!loc.length || !this.files.includes(last.item)) { UI.toast('TRACK REMOVED FROM LIBRARY'); return; }\n    const spec = this.fileSpec(last.item);\n    this.history[this.history.length - 1] = spec;\n    UI.renderHistory();\n    this.playSpec(spec, true);\n  },\n  setStation(id) {\n    if (id === 'local' && !this.files.length) { UI.toast('ADD YOUR WAVS FIRST'); setDrawer(true, 'music'); return; }\n    const was = this.station, active = !!this.cur;\n    this.station = id; settings.station = id;\n    if (id === 'local') settings.src = 'local'; else if (settings.src === 'local') settings.src = 'radio';\n    saveSettings(); syncSource(); UI.renderStations(); UI.renderStart(); UI.renderSpotify();\n    this.dropPrep();\n    if (id === 'spotify') {\n      if (!Sp.connected()) { setDrawer(true, 'music'); UI.focusSpotify(); return; }\n      if (active && this.cur !== SpPlayer) this.spStart();\n      else if (active && was === 'spotify') this.spStart(null);\n      return;\n    }\n    if (!active) return;\n    if (this.cur === SpPlayer) { SpPlayer.kill(); this.cur = null; this.playing = false; }\n    if (!this.ensureCtx()) return;\n    this.openGate();\n    if (this.cur) this.cur.kill(this.ctx.currentTime);\n    this.cur = null; this.playing = true; UI.syncPlay();\n    this.playNext();\n  },\n  /* avancer / reculer dans le morceau (en direct, ça sort du direct) */\n  seek(sec) {\n    const p = this.cur; if (!p || !(sec >= 0)) return;\n    if (p === SpPlayer) { Sp.seek(sec * 1000); return; }\n    if (p.kind === 'file' && this.ctx && p.seekTo) p.seekTo(sec, this.ctx.currentTime);\n  },\n  setVolume(v) {\n    settings.vol = v; if (this.kit) this.kit.vol.gain.setTargetAtTime(v * v, this.ctx.currentTime, 0.03);\n    Sp.setVolume(v);\n  }\n};\n\nconst settings = Object.assign({\n  cycle: 'auto', vol: 0.8, station: 'spotify', xfade: 4, visual: 'sunset', car: 'countach', sky: 'auto'\n}, store.get('settings', {}));\n// l'ancienne scène pixel a laissé place à la scène abstraite\nif (settings.visual === 'pixel') settings.visual = 'abstract';\nif (!['sunset', 'abstract'].includes(settings.visual)) settings.visual = 'sunset';\nfor (const k of ['scene', 'theme', 'themeCycle', 'px', 'react', 'weather', 'daycycle']) delete settings[k];\nif (!['spotify', 'local'].includes(settings.station)) settings.station = 'spotify';\nif (settings.cycle !== 'off') settings.cycle = 'auto';\nif (typeof settings.xfade !== 'number') settings.xfade = 4;\nfunction saveSettings() { store.set('settings', settings); }\n\nfunction resize() {\n  if (typeof Sunset !== 'undefined') Sunset.resize();\n  if (typeof Abstract !== 'undefined') Abstract.resize();\n}\n\n/* =====================================================================\n   SCÈNE « SUNSET »\n   ===================================================================== */\nconst Sunset = (() => {\n\n// Coucher de soleil sur la ville, voiture vue de profil, décor en parallaxe, météo.\n// Tout est dessiné en code (Canvas 2D). Les calques fixes et les sprites sont pré-rendus à chaque redimensionnement,\n// chaque image ne fait que les assembler avec leurs décalages.\n\nconst Q = new URLSearchParams(location.search);\nconst cv = document.getElementById('sunset');            // affichage : post-traitement WebGL\nconst sc = document.createElement('canvas');             // la scène, dessinée en 2D\nconst ctx = sc.getContext('2d', { alpha: false });\nconst SAT = 0.95;   // toute l'image un peu moins saturée que l'étalonnage de chaque ambiance\nlet post = null;\n\n// hauteurs, en fraction de la hauteur de l'écran\nconst Y = { sun: 0.305, city: 0.658, shore: 0.665, rail: 0.689, beam: 0.722, wall: 0.735, kerb: 0.758, road: 0.778, ground: 0.857, dash: 0.886 };\n// vitesses de défilement, en hauteurs d'écran par seconde (mesurées sur la vidéo de référence)\nconst V = { cloud: 0.006, shore: 0.09, palmFar: 0.8, palmNear: 1.3, lamp: 2.05, rail: 2.5, road: [2.8, 3.4, 4.3], dash: 3.9 };\nconst SUN_R = 0.148;   // rayon du soleil, en hauteur d'écran\n\nlet W = 0, H = 0, U = 1, CX = 0, S = null;\nlet t0 = 0, last = 0, ready = false, startCar = 0, onLabel = () => {};\n\nconst rnd = seed => { let s = seed >>> 0; return () => { s = (s + 0x6D2B79F5) | 0; let t = Math.imul(s ^ (s >>> 15), 1 | s); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };\nconst mk = (w, h) => { const c = document.createElement('canvas'); c.width = Math.max(1, Math.ceil(w)); c.height = Math.max(1, Math.ceil(h)); return c; };\nconst lerp = (a, b, t) => a + (b - a) * t;\nconst rgb = (c, a = 1) => `rgba(${c[0] | 0},${c[1] | 0},${c[2] | 0},${a})`;\nconst mixc = (a, b, t) => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];\n\n// flou de bougé horizontal : moyenne exacte de copies décalées (addition prémultipliée)\nfunction motionBlur(src, px) {\n  const k = Math.max(2, Math.min(10, Math.round(px / 1.5)));\n  const c = mk(src.width + px, src.height), g = c.getContext('2d');\n  g.globalCompositeOperation = 'lighter'; g.globalAlpha = 1 / k;\n  for (let i = 0; i < k; i++) g.drawImage(src, px * i / (k - 1), 0);\n  return c;\n}\n\nfunction glowSprite(r, g, b) {\n  const n = 128, c = mk(n, n), x = c.getContext('2d'), gr = x.createRadialGradient(n / 2, n / 2, 0, n / 2, n / 2, n / 2);\n  gr.addColorStop(0, `rgba(${r},${g},${b},1)`); gr.addColorStop(0.12, `rgba(${r},${g},${b},0.65)`);\n  gr.addColorStop(0.4, `rgba(${r},${g},${b},0.16)`); gr.addColorStop(1, `rgba(${r},${g},${b},0)`);\n  x.fillStyle = gr; x.fillRect(0, 0, n, n); return c;\n}\nfunction glow(spr, x, y, rx, ry, a) { ctx.globalAlpha = a; ctx.drawImage(spr, x - rx, y - ry, rx * 2, ry * 2); }\n\n/* ---------- post-traitement « film » ---------- */\n// Netteté adaptative au contraste (à la manière des upscalers type DLSS / FidelityFX CAS), aberration chromatique\n// vers les bords, bloom et halation, courbe de tons douce, vignettage et grain animé.\n// Sans WebGL (ou avec ?fx=0), la scène 2D s'affiche telle quelle.\n\nconst POST_FS = `\nprecision mediump float;\nvarying vec2 v;\nuniform sampler2D uS, uB;\nuniform vec2 uPx;\nuniform float uT, uSat;\nuniform vec3 uLift, uGain;\nfloat hash(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }\nvoid main() {\n  vec2 d = v - 0.5; float r2 = dot(d, d);\n  vec2 ca = d * r2 * 0.016;\n  vec3 c = vec3(texture2D(uS, v - ca).r, texture2D(uS, v).g, texture2D(uS, v + ca).b);\n  vec3 n = texture2D(uS, v + vec2(0.0, uPx.y)).rgb, s = texture2D(uS, v - vec2(0.0, uPx.y)).rgb;\n  vec3 e = texture2D(uS, v + vec2(uPx.x, 0.0)).rgb, w = texture2D(uS, v - vec2(uPx.x, 0.0)).rgb;\n  vec3 mn = min(c, min(min(n, s), min(e, w))), mx = max(c, max(max(n, s), max(e, w)));\n  vec3 k = -sqrt(clamp(min(mn, 1.0 - mx) / max(mx, vec3(0.0001)), 0.0, 1.0)) / 7.0;\n  c = clamp((c + (n + s + e + w) * k) / (1.0 + 4.0 * k), 0.0, 1.0);\n  vec3 b = texture2D(uB, v).rgb;\n  c += b * vec3(0.38, 0.3, 0.27) + b * b * vec3(0.18, 0.04, 0.0);\n  c = c / (1.0 + c * 0.12) * 1.06;\n  c = mix(vec3(0.012, 0.008, 0.02), vec3(1.0), c);\n  c *= 1.0 - smoothstep(0.1, 0.6, r2) * 0.42;\n  c = c * uGain + uLift;\n  c = mix(vec3(dot(c, vec3(0.299, 0.587, 0.114))), c, uSat);\n  float g = hash(gl_FragCoord.xy + fract(uT * 7.31) * 517.0) - 0.5;\n  float l = dot(c, vec3(0.299, 0.587, 0.114));\n  c += g * 0.05 * (0.3 + l * (1.0 - l) * 2.6);\n  gl_FragColor = vec4(c, 1.0);\n}`;\n\nfunction initPost() {\n  if (Q.get('fx') === '0') return null;\n  const gl = cv.getContext('webgl', { alpha: false, antialias: false, depth: false, stencil: false });\n  if (!gl) return null;\n  const sh = (type, src) => { const o = gl.createShader(type); gl.shaderSource(o, src); gl.compileShader(o); return gl.getShaderParameter(o, gl.COMPILE_STATUS) ? o : null; };\n  const vs = sh(gl.VERTEX_SHADER, 'attribute vec2 p; varying vec2 v; void main() { v = p * 0.5 + 0.5; gl_Position = vec4(p, 0.0, 1.0); }');\n  const fs = sh(gl.FRAGMENT_SHADER, POST_FS);\n  if (!vs || !fs) return null;\n  const prog = gl.createProgram(); gl.attachShader(prog, vs); gl.attachShader(prog, fs); gl.linkProgram(prog);\n  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return null;\n  gl.useProgram(prog);\n  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());\n  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);\n  const loc = gl.getAttribLocation(prog, 'p'); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);\n  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);\n  const tex = unit => {\n    const t = gl.createTexture(); gl.activeTexture(gl.TEXTURE0 + unit); gl.bindTexture(gl.TEXTURE_2D, t);\n    for (const [p, val] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, p, val);\n    return t;\n  };\n  const tS = tex(0), tB = tex(1);\n  gl.uniform1i(gl.getUniformLocation(prog, 'uS'), 0); gl.uniform1i(gl.getUniformLocation(prog, 'uB'), 1);\n  return { gl, tS, tB, uPx: gl.getUniformLocation(prog, 'uPx'), uT: gl.getUniformLocation(prog, 'uT'), uLift: gl.getUniformLocation(prog, 'uLift'), uGain: gl.getUniformLocation(prog, 'uGain'), uSat: gl.getUniformLocation(prog, 'uSat') };\n}\n\nfunction present(t) {\n  const gl = post.gl, bl = S.bloom, bg = bl.getContext('2d');\n  // bloom : la scène réduite au quart, seules les hautes lumières survivent, puis floutées\n  bg.filter = S.bloomFilter; bg.drawImage(sc, 0, 0, bl.width, bl.height); bg.filter = 'none';\n  gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, post.tS); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, sc);\n  gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, post.tB); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, bl);\n  const gd = WX.cur.grade;\n  gl.uniform1f(post.uT, t); gl.uniform3f(post.uLift, gd[0], gd[1], gd[2]); gl.uniform3f(post.uGain, gd[3], gd[4], gd[5]); gl.uniform1f(post.uSat, gd[6] * SAT);\n  gl.drawArrays(gl.TRIANGLES, 0, 3);\n}\n\n/* ---------- ciel, soleil, étoiles ---------- */\n\nfunction buildSky() {\n  const h = Math.ceil(H * Y.wall), c = mk(W, h), g = c.getContext('2d');\n  let gr = g.createLinearGradient(0, 0, 0, H * Y.city);\n  gr.addColorStop(0, '#0d1745'); gr.addColorStop(0.28, '#1c3176'); gr.addColorStop(0.52, '#3552a6'); gr.addColorStop(0.7, '#7a5c9c');\n  gr.addColorStop(0.84, '#b0687e'); gr.addColorStop(0.94, '#d87a6e'); gr.addColorStop(1, '#f6a07c');\n  g.fillStyle = gr; g.fillRect(0, 0, W, h);\n  paintFaintStars(g);\n  const sx = CX, sy = H * Y.sun, R = H * SUN_R;\n  g.globalCompositeOperation = 'screen';\n  gr = g.createRadialGradient(sx, sy, R * 0.8, sx, sy, H * 0.42);\n  gr.addColorStop(0, 'rgba(255,176,120,0.85)'); gr.addColorStop(0.35, 'rgba(240,130,120,0.22)'); gr.addColorStop(1, 'rgba(160,80,150,0)');\n  g.fillStyle = gr; g.fillRect(0, 0, W, h);\n  g.globalCompositeOperation = 'source-over';\n  gr = g.createRadialGradient(sx, sy - R * 0.25, R * 0.05, sx, sy, R);\n  gr.addColorStop(0, '#fffef6'); gr.addColorStop(0.45, '#fff4d2'); gr.addColorStop(0.75, '#ffd896'); gr.addColorStop(0.93, '#ffb46e'); gr.addColorStop(1, '#ff9a5e');\n  g.fillStyle = gr; g.beginPath(); g.arc(sx, sy, R, 0, Math.PI * 2); g.fill();\n  gr = g.createRadialGradient(sx, sy, R * 0.96, sx, sy, R * 1.3);\n  gr.addColorStop(0, 'rgba(255,214,160,0.7)'); gr.addColorStop(1, 'rgba(255,170,130,0)');\n  g.fillStyle = gr; g.beginPath(); g.arc(sx, sy, R * 1.3, 0, Math.PI * 2); g.fill();\n  return c;\n}\n\n// étoiles qui scintillent (les plus fines sont peintes une fois pour toutes dans le ciel)\nfunction buildStars() {\n  const r = rnd(7), list = [], bright = [], n = Math.round(W * H / 3000), sy = H * Y.sun, R = H * SUN_R;\n  const cols = ['#ffffff', '#ffffff', '#dfe8ff', '#cad8ff', '#fff0dc', '#ffe2c8'];\n  for (let i = 0; i < n; i++) {\n    const x = r() * W, y = Math.pow(r(), 1.4) * H * 0.58;\n    if (Math.hypot(x - CX, y - sy) < R * 2.2) continue;\n    const fade = Math.max(0, 1 - y / (H * 0.6));\n    list.push({ x, y, s: Math.max(1, (0.6 + r() * r() * 1.8) * U), a: (0.3 + r() * 0.7) * fade, f: 0.4 + r() * 2.6, p: r() * 6.3, col: cols[(r() * cols.length) | 0] });\n    if (r() < 0.035 && y < H * 0.4) bright.push({ x, y, r: (1.2 + r() * 1.6) * U, f: 0.5 + r() * 1.5, p: r() * 6.3 });\n  }\n  return { list, bright };\n}\n\nfunction paintFaintStars(g) {\n  const r = rnd(9), n = Math.round(W * H / 700), sy = H * Y.sun, R = H * SUN_R;\n  g.fillStyle = '#fff';\n  for (let i = 0; i < n; i++) {\n    const x = r() * W, y = Math.pow(r(), 1.3) * H * 0.6;\n    if (Math.hypot(x - CX, y - sy) < R * 2.6) continue;\n    g.globalAlpha = (0.12 + 0.45 * r() * r()) * Math.max(0, 1 - y / (H * 0.62));\n    const s = r() < 0.85 ? Math.max(1, 0.8 * U) : Math.max(1, 1.3 * U);\n    g.fillRect(x, y, s, s);\n  }\n  g.globalAlpha = 1;\n}\n\n/* ---------- nuages ---------- */\n\nfunction cloud(r, w, h, wisp) {\n  const c = mk(w, h), g = c.getContext('2d');\n  const n = wisp ? 12 : 8 + (r() * 10 | 0), blobs = [];\n  for (let i = 0; i < n; i++) {\n    const t = (i + r() * 0.8) / n, bell = Math.max(0.15, 1 - Math.pow((t - 0.5) * 2, 2));\n    const br = wisp ? h * 0.5 : h * (0.2 + 0.3 * bell * (0.55 + 0.45 * r()));\n    blobs.push([w * (0.08 + 0.84 * t), wisp ? h * 0.5 : h * 0.8 - br * (0.5 + 0.3 * r()), br]);\n  }\n  const blob = (bx, by, br, col, sx) => {\n    g.setTransform(sx, 0, 0, 1, bx, by);\n    const gr = g.createRadialGradient(0, 0, 0, 0, 0, br);\n    gr.addColorStop(0, rgb(col, 1)); gr.addColorStop(0.55, rgb(col, 0.88)); gr.addColorStop(1, rgb(col, 0));\n    g.fillStyle = gr; g.fillRect(-br, -br, br * 2, br * 2);\n  };\n  const sx = wisp ? 3 : 1;\n  for (const [bx, by, br] of blobs) blob(bx, by, br, [255, 255, 255], sx);\n  g.setTransform(1, 0, 0, 1, 0, 0);\n  g.globalCompositeOperation = 'source-in';\n  const gr = g.createLinearGradient(0, 0, 0, h);\n  gr.addColorStop(0, 'rgb(96,92,168)'); gr.addColorStop(0.5, 'rgb(214,120,150)'); gr.addColorStop(1, 'rgb(255,178,140)');\n  g.fillStyle = gr; g.fillRect(0, 0, w, h);\n  if (!wisp) {\n    // éclairés par en dessous : on assombrit tout sauf le bord inférieur\n    g.globalCompositeOperation = 'source-atop';\n    for (const [bx, by, br] of blobs) blob(bx, by - h * 0.22, br * 0.95, [70, 70, 140], 1);\n    g.setTransform(1, 0, 0, 1, 0, 0);\n  }\n  return c;\n}\n\n// bruit de valeur fractal, périodique en x (la bande de nuages se raccorde sur elle-même)\nfunction fbm(seed, w, h, cellsX, cellsY, oct) {\n  const r = rnd(seed), out = new Float32Array(w * h);\n  let amp = 1, tot = 0;\n  for (let o = 0; o < oct; o++) {\n    const cx = cellsX << o, cy = cellsY << o, grid = new Float32Array(cx * (cy + 1));\n    for (let i = 0; i < grid.length; i++) grid[i] = r();\n    for (let y = 0; y < h; y++) {\n      const fy = y / h * cy, iy = fy | 0, ty = fy - iy, sy = ty * ty * (3 - 2 * ty), r0 = iy * cx, r1 = r0 + cx;\n      for (let x = 0; x < w; x++) {\n        const fx = x / w * cx, ix = fx | 0, tx = fx - ix, sx = tx * tx * (3 - 2 * tx), ix1 = (ix + 1) % cx;\n        const a = grid[r0 + ix], b = grid[r0 + ix1], c = grid[r1 + ix], d = grid[r1 + ix1];\n        const top = a + (b - a) * sx, bot = c + (d - c) * sx;\n        out[y * w + x] += amp * (top + (bot - top) * sy);\n      }\n    }\n    tot += amp; amp *= 0.52;\n  }\n  for (let i = 0; i < out.length; i++) out[i] /= tot;\n  return out;\n}\n\nfunction buildClouds() {\n  const TW = Math.ceil(Math.max(W, H * 1.78) * 1.6), CH = Math.ceil(H * Y.city), c = mk(TW, CH), g = c.getContext('2d'), r = rnd(23);\n  // cumulus déchiquetés : densité fractale, éclairés par en dessous par le soleil couchant\n  const q = 2, w = Math.ceil(TW / q), h = Math.ceil(CH / q);\n  const d = fbm(29, w, h, Math.max(4, Math.round(TW / (H * 0.2))), Math.max(2, Math.round(CH / (H * 0.07))), 6);\n  const img = new ImageData(w, h), px = img.data, k = Math.max(1, Math.round(H * 0.012 / q));\n  const sh = [74, 80, 150], mid = [200, 100, 130], lit = [255, 142, 126];\n  for (let y = 0; y < h; y++) {\n    const fy = y / h, th = 0.465 + 0.08 * Math.min(1, Math.abs(fy - 0.16) / 0.34) - (fy > 0.5 && fy < 0.7 ? 0.02 : 0) + (fy > 0.8 ? (fy - 0.8) * 0.6 : 0);\n    for (let x = 0; x < w; x++) {\n      const i = y * w + x, v = d[i];\n      const a = Math.min(1, Math.max(0, (v - th) / 0.07));\n      if (a <= 0) continue;\n      const below = y + k < h ? d[i + k * w] : 0;\n      const l = Math.min(1, Math.max(0, (v - below) * 9 + 0.15)), core = Math.min(1, (v - th) / 0.25);\n      const col = l > 0.5 ? mixc(mid, lit, (l - 0.5) * 2) : mixc(sh, mid, l * 2);\n      const dk = 1 - 0.25 * core * (1 - l);\n      px[i * 4] = col[0] * dk; px[i * 4 + 1] = col[1] * dk; px[i * 4 + 2] = col[2] * dk; px[i * 4 + 3] = 255 * a * a * (3 - 2 * a) * 0.96;\n    }\n  }\n  const lo = mk(w, h); lo.getContext('2d').putImageData(img, 0, 0);\n  g.imageSmoothingQuality = 'high'; g.drawImage(lo, 0, 0, w * q, h * q);\n  // fines traînées devant le soleil\n  const put = (spr, x, y, a) => { g.globalAlpha = a; g.drawImage(spr, x, y); if (x + spr.width > TW) g.drawImage(spr, x - TW, y); };\n  for (let i = 0, n = Math.round(TW / H * 5); i < n; i++) { const cw = H * (0.25 + 0.6 * r()), chh = H * (0.01 + 0.012 * r()); put(cloud(r, cw, chh, true), r() * TW, H * (0.22 + 0.26 * r()), 0.5); }\n  return { c, TW };\n}\n\n/* ---------- ville ---------- */\n\nfunction buildCity() {\n  const base = Math.round(H * Y.city), c = mk(W, base), g = c.getContext('2d'), r = rnd(11), R = H * SUN_R, sy = H * Y.sun;\n  const blinks = [];\n  // du plus lointain au plus proche ; chaque plan est voilé par la brume avant que le suivant ne le recouvre\n  const layers = [\n    { h: [0.07, 0.22], w: [0.015, 0.04], gap: [-0.004, 0.002], body: [128, 76, 96], top: [110, 66, 92], win: 0.3, wa: 0.4, sc: 0.5, haze: 0.18 },\n    { h: [0.1, 0.3], w: [0.02, 0.045], gap: [-0.004, 0.006], body: [92, 50, 68], top: [78, 44, 64], win: 0.36, wa: 0.6, sc: 0.62, haze: 0.16, roof: 1 },\n    { h: [0.14, 0.38], w: [0.024, 0.055], gap: [-0.002, 0.02], body: [64, 32, 48], top: [48, 26, 42], win: 0.42, wa: 0.8, sc: 0.76, haze: 0.12, roof: 1 },\n    { h: [0.18, 0.46], w: [0.03, 0.065], gap: [0.02, 0.09], body: [40, 20, 30], top: [26, 14, 24], win: 0.42, wa: 1, sc: 0.9, haze: 0.05, roof: 1, near: 1 },\n    { h: [0.018, 0.055], w: [0.03, 0.08], gap: [-0.01, 0], body: [60, 30, 38], top: [48, 26, 34], win: 0.62, wa: 1, sc: 0.7, haze: 0 },\n  ];\n  const fx = { blinks, flick: [] };\n  // profondeur de champ : les trois plans lointains sont dessinés à part puis légèrement floutés\n  const far = mk(W, base), fg = far.getContext('2d');\n  layers.forEach((L, li) => {\n    const t = li < 3 ? fg : g;\n    let x = -r() * H * 0.05;\n    while (x < W) {\n      const bw = H * lerp(L.w[0], L.w[1], r()), mid = x + bw / 2;\n      const dc = Math.min(1, Math.abs(mid - CX) / (W * 0.5));\n      let bh = H * lerp(L.h[0], L.h[1], Math.pow(r(), 0.8)) * (1 - 0.1 * dc);\n      // le bas du soleil reste visible entre les tours\n      const sunBottom = sy + R * 0.55;\n      if (Math.abs(mid - CX) < R * 0.8 && base - bh < sunBottom) bh = base - sunBottom - r() * H * 0.04;\n      building(t, x, base, bw, bh, L, r, fx);\n      x += bw + H * lerp(L.gap[0], L.gap[1], r());\n    }\n    if (L.haze) { t.globalCompositeOperation = 'source-atop'; t.fillStyle = `rgba(220,110,110,${L.haze})`; t.fillRect(0, 0, W, base); t.globalCompositeOperation = 'source-over'; }\n    if (li === 2) { g.filter = `blur(${(0.9 * U).toFixed(2)}px)`; g.drawImage(far, 0, 0); g.filter = 'none'; }\n  });\n  g.globalCompositeOperation = 'source-atop';\n  let gr = g.createLinearGradient(0, base - H * 0.3, 0, base);\n  gr.addColorStop(0, 'rgba(236,120,110,0)'); gr.addColorStop(1, 'rgba(236,120,110,0.3)');\n  g.fillStyle = gr; g.fillRect(0, 0, W, base);\n  gr = g.createRadialGradient(CX, sy, R, CX, sy, H * 0.62);\n  gr.addColorStop(0, 'rgba(255,170,130,0.22)'); gr.addColorStop(1, 'rgba(255,170,130,0)');\n  g.fillStyle = gr; g.fillRect(0, 0, W, base);\n  g.globalCompositeOperation = 'source-over';\n  return { c, blinks, flick: fx.flick };\n}\n\nfunction building(g, x, base, bw, bh, L, r, fx) {\n  const top = base - bh;\n  let gr = g.createLinearGradient(0, top, 0, base);\n  gr.addColorStop(0, rgb(L.top)); gr.addColorStop(1, rgb(L.body));\n  g.fillStyle = gr; g.fillRect(x, top, bw, bh);\n  // toits : retraits, flèches\n  if (L.roof) {\n    const k = r();\n    g.fillStyle = rgb(L.top);\n    if (k < 0.32) { const sw = bw * (0.45 + 0.25 * r()), sh = bh * (0.04 + 0.06 * r()); g.fillRect(x + (bw - sw) / 2, top - sh, sw, sh); if (r() < 0.5) { const s2 = sw * 0.55, h2 = sh * 0.8; g.fillRect(x + (bw - s2) / 2, top - sh - h2, s2, h2); } }\n    else if (k < 0.42) { g.beginPath(); g.moveTo(x, top); g.lineTo(x + bw / 2, top - bw * (0.6 + 0.8 * r())); g.lineTo(x + bw, top); g.fill(); }\n    else if (k < 0.52) { g.beginPath(); g.moveTo(x, top); g.lineTo(x + bw, top - bw * 0.35); g.lineTo(x + bw, top); g.fill(); }\n  }\n  // face tournée vers le soleil et liseré\n  const toSun = x + bw / 2 < CX ? 1 : -1, close = Math.max(0, 1 - Math.abs(x + bw / 2 - CX) / (H * 0.9));\n  const fw = bw * (0.2 + 0.25 * r());\n  gr = g.createLinearGradient(0, top, 0, base);\n  gr.addColorStop(0, `rgba(255,170,130,${0.06 + 0.26 * close})`); gr.addColorStop(1, `rgba(255,130,130,${0.04 + 0.1 * close})`);\n  g.fillStyle = gr; g.fillRect(toSun > 0 ? x + bw - fw : x, top, fw, bh);\n  g.fillStyle = `rgba(255,210,170,${(0.2 + 0.65 * close) * (0.3 + 0.7 * L.sc)})`; g.fillRect(toSun > 0 ? x + bw - 1.5 * U : x, top, 1.5 * U, bh);\n  // reflets verticaux du vitrage côté soleil\n  if (L.sc >= 0.7) {\n    g.fillStyle = `rgba(255,190,160,${0.05 + 0.12 * close})`;\n    for (let i = 0, n = 1 + (r() * 3 | 0); i < n; i++) g.fillRect((toSun > 0 ? x + bw - fw : x) + r() * fw, top, Math.max(1, U * (1 + 2 * r())), bh);\n  }\n  // fenêtres : petites, nombreuses, par étages plus ou moins occupés ; certaines tours ont des plateaux de bureaux allumés\n  const ww = Math.max(1, H * 0.0027 * L.sc), wh = Math.max(1, H * 0.0036 * L.sc), px = ww * 2, py = wh * 1.9;\n  const busy = L.win * (0.3 + 0.8 * r()), office = L.sc >= 0.6 && r() < 0.18, warm = r() < 0.8;\n  let floor = 0;\n  for (let yy = top + py; yy < base - py * 0.5; yy += py, floor++) {\n    if (office && r() < 0.3) {\n      g.fillStyle = warm ? '#ffe2b8' : '#d8e6ff'; g.globalAlpha = L.wa * (0.2 + 0.2 * r());\n      g.fillRect(x + px * 0.4, yy, bw - px * 0.8, wh); continue;\n    }\n    const fl = r() < 0.2 ? 0.15 : r() < 0.15 ? 2 : 1;\n    for (let xx = x + px * 0.5; xx < x + bw - px * 0.6; xx += px) {\n      if (r() > busy * fl) {\n        if (L.near && yy < base - H * 0.06 && fx.flick.length < 90 && r() < 0.006) fx.flick.push({ x: xx, y: yy, w: ww, h: wh, p: r() * 100, f: 0.05 + 0.15 * r() });\n        continue;\n      }\n      const k = r();\n      g.fillStyle = k < 0.72 ? '#ffcc88' : k < 0.92 ? '#ffe6c4' : '#a8c8ff';\n      g.globalAlpha = L.wa * (0.35 + 0.65 * r());\n      g.fillRect(xx, yy, ww, wh);\n    }\n    // joints d'étage\n    if (L.sc >= 0.7 && floor % 4 === 3) { g.globalAlpha = 0.18; g.fillStyle = '#000'; g.fillRect(x, yy + wh * 1.4, bw, Math.max(1, U * 0.8)); }\n  }\n  g.globalAlpha = 1;\n  // couronne éclairée par le bas\n  if (L.sc >= 0.6 && r() < 0.3) {\n    const ch = bh * (0.04 + 0.06 * r()), gr2 = g.createLinearGradient(0, top, 0, top + ch);\n    const col = r() < 0.75 ? '255,196,150' : '200,220,255';\n    gr2.addColorStop(0, `rgba(${col},${0.5 * L.wa})`); gr2.addColorStop(1, `rgba(${col},0)`);\n    g.fillStyle = gr2; g.fillRect(x, top, bw, ch);\n    g.fillStyle = `rgba(${col},${0.8 * L.wa})`; g.fillRect(x, top, bw, Math.max(1, U));\n  }\n  // toits : châteaux d'eau, blocs de climatisation\n  if (L.sc >= 0.7 && !L.near && bh < H * 0.3 && r() < 0.35) {\n    const tw = Math.max(3, H * 0.008 * L.sc), th = tw * 1.2, tx = x + bw * (0.2 + 0.5 * r());\n    g.fillStyle = rgb(L.top);\n    g.fillRect(tx, top - th * 1.9, tw, th);\n    g.beginPath(); g.moveTo(tx - tw * 0.1, top - th * 1.9); g.lineTo(tx + tw / 2, top - th * 2.4); g.lineTo(tx + tw * 1.1, top - th * 1.9); g.fill();\n    g.fillRect(tx + tw * 0.1, top - th * 0.7, Math.max(1, U), th * 0.7); g.fillRect(tx + tw * 0.8, top - th * 0.7, Math.max(1, U), th * 0.7);\n  }\n  if (L.sc >= 0.6 && r() < 0.5) {\n    g.fillStyle = rgb(L.top);\n    for (let i = 0, n = 1 + (r() * 3 | 0); i < n; i++) { const bw2 = bw * (0.1 + 0.15 * r()), bh2 = H * 0.004 * (1 + r()); g.fillRect(x + r() * (bw - bw2), top - bh2, bw2, bh2); }\n  }\n  // antennes\n  if (L.near && r() < 0.35) {\n    const ah = H * (0.02 + 0.035 * r()), ax = x + bw * (0.3 + 0.4 * r());\n    g.fillStyle = rgb(L.top); g.fillRect(ax, top - ah, Math.max(1, 1.6 * U), ah);\n    g.fillRect(ax - H * 0.003, top - ah * 0.6, H * 0.006 + 1.6 * U, Math.max(1, U));\n    fx.blinks.push({ x: ax, y: top - ah, p: r() * 6.3 });\n  }\n}\n\n/* ---------- eau, quai, palmiers, lampadaires ---------- */\n\nfunction buildWater() {\n  const y0 = Math.round(H * Y.shore), y1 = Math.round(H * Y.wall), h = y1 - y0, c = mk(W, h), g = c.getContext('2d'), r = rnd(31);\n  let gr = g.createLinearGradient(0, 0, 0, h);\n  gr.addColorStop(0, '#8a4048'); gr.addColorStop(0.3, '#5a2630'); gr.addColorStop(1, '#2e141a');\n  g.fillStyle = gr; g.fillRect(0, 0, W, h);\n  g.fillStyle = '#ffd0a0';\n  for (let i = 0; i < 70; i++) {\n    const yy = r() * h, ww = H * 0.11 * (1 - yy / h * 0.5) * (0.3 + 0.7 * r());\n    g.globalAlpha = (0.25 + 0.5 * r()) * (1 - yy / h * 0.6);\n    g.fillRect(CX - ww / 2 + (r() - 0.5) * H * 0.02, yy, ww, Math.max(1, H * 0.0022));\n  }\n  for (let i = 0, n = Math.round(W / H * 140); i < n; i++) {\n    g.fillStyle = r() < 0.8 ? '#ffc890' : '#ff9ac0';\n    g.globalAlpha = 0.12 + 0.3 * r();\n    g.fillRect(r() * W, r() * h * 0.5, Math.max(1, H * 0.0018), H * (0.005 + 0.02 * r()));\n  }\n  g.globalAlpha = 1;\n  const shimmer = [];\n  for (let i = 0; i < 46; i++) shimmer.push({ x: CX + (r() - 0.5) * H * 0.16, y: y0 + r() * h * 0.9, w: H * (0.008 + 0.03 * r()), f: 1 + r() * 3, p: r() * 6.3 });\n  return { c, y0, shimmer };\n}\n\nfunction tinyPalm(g, x, y, h, r) {\n  const lean = (r() - 0.5) * h * 0.3;\n  g.lineWidth = Math.max(1, h * 0.06);\n  g.beginPath(); g.moveTo(x, y); g.quadraticCurveTo(x + lean * 0.2, y - h * 0.5, x + lean, y - h); g.stroke();\n  g.lineWidth = Math.max(1, h * 0.05);\n  for (let i = 0; i < 7; i++) {\n    const a = (i / 7) * Math.PI * 2 + r() * 0.5, dx = Math.cos(a) * h * 0.45, dy = Math.sin(a) * h * 0.18 - h * 0.08;\n    g.beginPath(); g.moveTo(x + lean, y - h); g.quadraticCurveTo(x + lean + dx * 0.6, y - h + dy - h * 0.06, x + lean + dx, y - h + dy + h * 0.16); g.stroke();\n  }\n}\n\nfunction buildShore() {\n  const TW = Math.ceil(Math.max(W, H * 1.78) * 1.3), h = Math.ceil(H * 0.06), c = mk(TW, h), g = c.getContext('2d'), r = rnd(37);\n  g.strokeStyle = 'rgba(44,24,52,0.75)'; g.lineCap = 'round';\n  for (let x = 0; x < TW; x += H * (0.02 + 0.07 * r())) {\n    const ph = H * (0.02 + 0.026 * r());\n    if (x + ph < TW) tinyPalm(g, x, h, ph, r);\n  }\n  for (let x = r() * H * 0.03; x < TW; x += H * (0.03 + 0.03 * r())) {\n    const gr = g.createRadialGradient(x, h - H * 0.006, 0, x, h - H * 0.006, H * 0.006);\n    gr.addColorStop(0, 'rgba(255,236,220,0.95)'); gr.addColorStop(1, 'rgba(255,170,190,0)');\n    g.fillStyle = gr; g.fillRect(x - H * 0.006, h - H * 0.012, H * 0.012, H * 0.012);\n  }\n  return { c, TW };\n}\n\n// Palmier vu à contre-jour : tronc annelé en S, palmes mortes pendantes, noix de coco, palmes en fontaine\n// faites de folioles effilées. Géométrie calculée une fois puis tracée deux fois : un liseré chaud décalé vers le haut,\n// puis la silhouette. dof : flou de profondeur (palmiers lointains), blurPx : flou de bougé horizontal.\nfunction buildPalm(seed, h, blurPx, haze, dof) {\n  const r = rnd(seed), w = Math.ceil(h * 1.2), hh = Math.ceil(h * 1.02);\n  const c = mk(w, hh), g = c.getContext('2d');\n  const bx = w * 0.5, by = hh, lean = (r() - 0.5) * h * 0.24;\n  const tx = bx + lean, ty = h * 0.22, dark = '#1a1119';\n  // tronc : cubique en S léger, renflé au pied\n  const c1x = bx + (r() - 0.5) * h * 0.06, c1y = lerp(by, ty, 0.35), c2x = tx - lean * (0.2 + 0.4 * r()), c2y = lerp(by, ty, 0.7);\n  const N = 60, Lp = [], Rp = [];\n  for (let i = 0; i <= N; i++) {\n    const t = i / N, u = 1 - t;\n    const x = u * u * u * bx + 3 * u * u * t * c1x + 3 * u * t * t * c2x + t * t * t * tx;\n    const y = u * u * u * by + 3 * u * u * t * c1y + 3 * u * t * t * c2y + t * t * t * ty;\n    const dx = 3 * u * u * (c1x - bx) + 6 * u * t * (c2x - c1x) + 3 * t * t * (tx - c2x);\n    const dy = 3 * u * u * (c1y - by) + 6 * u * t * (c2y - c1y) + 3 * t * t * (ty - c2y), dl = Math.hypot(dx, dy) || 1;\n    const tw = lerp(h * 0.02, h * 0.011, t) * (1 + 0.7 * Math.max(0, 1 - t / 0.07)) / 2;\n    Lp.push([x - dy / dl * tw, y + dx / dl * tw]); Rp.push([x + dy / dl * tw, y - dx / dl * tw]);\n  }\n  g.fillStyle = dark; g.beginPath();\n  Lp.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y));\n  for (let i = N; i >= 0; i--) g.lineTo(Rp[i][0], Rp[i][1]);\n  g.closePath(); g.fill();\n  g.lineWidth = Math.max(1, h * 0.0018);\n  for (let i = 1; i < N; i++) {\n    g.strokeStyle = i % 2 ? 'rgba(255,160,120,0.1)' : 'rgba(0,0,0,0.45)';\n    g.beginPath(); g.moveTo(Lp[i][0], Lp[i][1]); g.lineTo(Rp[i][0], Rp[i][1]); g.stroke();\n  }\n  g.strokeStyle = 'rgba(255,150,110,0.28)'; g.lineWidth = Math.max(1, h * 0.0016);\n  for (const side of [Lp, Rp]) { g.beginPath(); side.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y)); g.stroke(); }\n\n  // une palme : nervure courbée et folioles effilées (base large, pointe fine)\n  const frond = (dx, dy, len, droop, leafLen, leafDown, out) => {\n    const pts = [];\n    for (let k = 0; k <= 24; k++) { const s = k / 24; pts.push([tx + dx * len * s, ty + dy * len * s + droop * s * s]); }\n    out.spines.push(pts);\n    for (let k = 2; k <= 24; k++) {\n      const s = k / 24, [px, py] = pts[k], [qx, qy] = pts[k - 1];\n      const tl = Math.hypot(px - qx, py - qy) || 1, ux = (px - qx) / tl, uy = (py - qy) / tl;\n      const ll = len * (leafLen * Math.sin(Math.PI * Math.min(1, s * 1.05)) + 0.03) * (0.8 + 0.4 * r());\n      if (r() < 0.06) continue;   // foliole manquante : la palme n'est pas un peigne parfait\n      for (const side of [-1, 1]) {\n        let lx = -uy * side * 0.55 + ux * 0.75, ly = ux * side * 0.55 + uy * 0.75 + leafDown;\n        const ln = Math.hypot(lx, ly); lx /= ln; ly /= ln;\n        out.leaves.push([px, py, px + lx * ll * 0.6, py + ly * ll * 0.3, px + lx * ll, py + ly * ll, -ly, lx, h * 0.0034 * (1 - s * 0.55)]);\n      }\n    }\n  };\n  const draw = (set, col, oy) => {\n    g.strokeStyle = col; g.fillStyle = col; g.lineCap = 'round';\n    for (const pts of set.spines) {\n      for (let k = 1; k < pts.length; k++) {\n        g.lineWidth = Math.max(1, lerp(h * 0.008, h * 0.0018, k / pts.length));\n        g.beginPath(); g.moveTo(pts[k - 1][0], pts[k - 1][1] + oy); g.lineTo(pts[k][0], pts[k][1] + oy); g.stroke();\n      }\n    }\n    g.beginPath();\n    for (const [x0, y0, x1, y1, x2, y2, nx, ny, lw] of set.leaves) {\n      g.moveTo(x0 + nx * lw, y0 + ny * lw + oy); g.quadraticCurveTo(x1, y1 + oy, x2, y2 + oy);\n      g.quadraticCurveTo(x1, y1 + oy, x0 - nx * lw, y0 - ny * lw + oy); g.closePath();\n    }\n    g.fill();\n  };\n\n  // palmes mortes, brunes, qui pendent contre le tronc\n  const dead = { spines: [], leaves: [] };\n  for (let i = 0, n = 2 + (r() * 4 | 0); i < n; i++) frond((r() - 0.5) * 0.7, 0.75 + 0.2 * r(), h * (0.09 + 0.07 * r()), h * 0.02, 0.14, 1.4, dead);\n  draw(dead, '#2c1a14', 0);\n  // cœur de la couronne et noix de coco\n  g.fillStyle = dark; g.beginPath(); g.ellipse(tx, ty + h * 0.004, h * 0.02, h * 0.014, 0, 0, Math.PI * 2); g.fill();\n  for (let i = 0, n = 3 + (r() * 5 | 0); i < n; i++) {\n    const cx = tx + (r() - 0.5) * h * 0.032, cy = ty + h * (0.008 + 0.014 * r()), cr = h * (0.0055 + 0.002 * r());\n    g.fillStyle = '#170d0e'; g.beginPath(); g.arc(cx, cy, cr, 0, Math.PI * 2); g.fill();\n    g.strokeStyle = 'rgba(255,160,120,0.35)'; g.lineWidth = Math.max(1, h * 0.0012);\n    g.beginPath(); g.arc(cx, cy, cr * 0.8, Math.PI * 1.1, Math.PI * 1.6); g.stroke();\n  }\n  // palmes vertes en fontaine : elles montent puis retombent\n  const live = { spines: [], leaves: [] };\n  const nf = 18 + (r() * 8 | 0);\n  let reach = 0;\n  for (let i = 0; i < nf; i++) {\n    const a = (i / nf) * Math.PI * 2 + r() * 0.35;\n    const dx = Math.cos(a), dy = Math.sin(a) * 0.25 - 0.2 - 0.3 * r();\n    const len = h * (0.19 + 0.12 * r()) * (0.75 + 0.25 * Math.abs(dx)) * (r() < 0.12 ? 0.6 : 1);\n    reach = Math.max(reach, len);\n    frond(dx, dy, len, len * (0.6 + 0.45 * r()) * (0.5 + 0.5 * Math.abs(dx)), 0.2, 0.4, live);\n  }\n  draw(live, 'rgba(255,150,100,0.75)', -Math.max(1, h * 0.003));\n  draw(live, dark, 0);\n  // contre-jour : le bout des palmes laisse passer la lumière\n  g.globalCompositeOperation = 'source-atop';\n  const gr = g.createRadialGradient(tx, ty, reach * 0.25, tx, ty, reach * 1.1);\n  gr.addColorStop(0, 'rgba(255,150,100,0)'); gr.addColorStop(1, 'rgba(255,160,110,0.3)');\n  g.fillStyle = gr; g.fillRect(0, 0, w, hh);\n  if (haze) { g.fillStyle = `rgba(130,70,90,${haze})`; g.fillRect(0, 0, w, hh); }\n  g.globalCompositeOperation = 'source-over';\n  let out = c;\n  if (dof) { out = mk(w, hh); const og = out.getContext('2d'); og.filter = `blur(${dof.toFixed(2)}px)`; og.drawImage(c, 0, 0); }\n  if (blurPx > 1) out = motionBlur(out, blurPx);\n  return { c: out, ax: w * 0.5 + blurPx / 2, ay: hh };\n}\n\nconst CARS = [\n  {\n    id: 'countach', name: 'Countach', len: 4140, width: 2000, ws: [300, 452], rw: [612, 700], paint: 'red', rim: 'dial',\n    body: [\n      [30, 34, 6], [14, 52, 8], [18, 86, 10], [58, 126, 14], [100, 160, 12], [190, 184, 40], [300, 200, 18], [452, 246, 34], [612, 248, 24], [700, 230, 20],\n      [868, 214, 10], [985, 204, 8], [1000, 188, 6], [1000, 112, 6], [994, 72, 8], [978, 38, 6],\n      [902, 40, 3], [892, 108, 30], [860, 146, 28], [776, 148, 28], [744, 112, 30], [734, 40, 3],\n      [312, 38, 3], [302, 106, 30], [272, 138, 28], [176, 138, 28], [146, 106, 30], [136, 40, 3],\n    ],\n    top: [[18, 86], [58, 126, 14], [100, 160, 12], [190, 184, 40], [300, 200, 18], [452, 246, 34], [612, 248, 24], [700, 230, 20], [868, 214, 10], [985, 204, 8], [1000, 188]],\n    archF: [[136, 30], [146, 106, 30], [176, 138, 28], [272, 138, 28], [302, 106, 30], [312, 30]],\n    archR: [[734, 30], [744, 112, 30], [776, 148, 28], [860, 146, 28], [892, 108, 30], [902, 30]],\n    glass: [[[314, 184, 4], [446, 240, 22], [592, 242, 8], [602, 182, 4]], [[614, 184, 3], [606, 240, 6], [650, 236, 10], [690, 200, 4]]],\n    dark: [[[506, 160, 3], [640, 170, 3], [640, 132, 3], [606, 129, 3]], [[712, 226, 4], [800, 218, 4], [796, 208, 4], [716, 212, 4]]],\n    mirror: [[298, 206, 3], [332, 214, 3], [336, 224, 3], [304, 222, 3]],\n    wing: [[840, 220, 4], [1010, 248, 4], [1018, 272, 6], [868, 244, 6]],\n    struts: [[[880, 212], [884, 234]], [[958, 204], [964, 250]]],\n    lamps: [\n      [[[106, 158, 2], [112, 170, 3], [138, 176, 3], [136, 166, 2]], '#fff4e6'], [[[148, 170, 2], [154, 180, 3], [178, 186, 3], [178, 177, 2]], '#fff4e6'],\n      [[[24, 66, 2], [40, 76, 2], [42, 70, 2], [26, 60, 2]], '#ffa040'], [[[968, 180, 2], [1000, 182, 2], [1000, 164, 2], [970, 164, 2]], '#ff3a30'],\n    ],\n    wheels: [[224, 62], [818, 66]], beam: [150, 176],\n    glows: [['W', 124, 170, 0.03, 0.026, 0.8], ['W', 165, 179, 0.03, 0.026, 0.8], ['O', 32, 68, 0.02, 0.02, 0.7], ['R', 990, 172, 0.04, 0.03, 0.85]],\n  },\n  {\n    // Toyota Supra A80 : nez rond et bas, long capot, bulle de pavillon, lunette fuyante, poupe courte, aileron sur arceaux\n    id: 'supra', name: 'Supra MK4', len: 4520, width: 1810, ws: [385, 548], rw: [700, 850], paint: 'black', rim: 'spoke5', caliper: '#c42a20', drop: 4,\n    profile: [\n      [22, 30, 6], [6, 48, 10], [0, 78, 18], [4, 104, 18], [22, 128, 24], [60, 146, 30], [150, 162, 60], [270, 180, 80], [385, 205, 16],\n      [548, 280, 70], [640, 284, 70], [700, 270, 60], [850, 224, 30], [950, 222, 14], [990, 216, 8], [1000, 190, 8], [999, 120, 10], [992, 62, 10], [972, 38, 6],\n    ],\n    sill: 34, arch: 13,\n    glass: [[[398, 206, 4], [540, 272, 30], [640, 276, 40], [700, 262, 30], [776, 238, 12], [740, 224, 4]]],\n    dark: [[[8, 54, 4], [70, 58, 4], [72, 44, 4], [12, 40, 4]]],\n    mirror: [[400, 206, 4], [438, 214, 6], [442, 228, 6], [404, 226, 4]],\n    wing: [[858, 262, 4], [1006, 268, 4], [1008, 280, 6], [866, 278, 6]],\n    struts: [[[884, 224], [890, 250, 30], [904, 266]], [[958, 222], [966, 248, 30], [980, 268]]],\n    lamps: [\n      [[[8, 98, 1], [58, 130, 2], [94, 140, 1], [60, 122, 2], [16, 92, 1]], '#fff2e2'], [[[22, 74, 3], [46, 78, 3], [46, 70, 3], [22, 66, 3]], '#ffa040'],\n      [[[984, 206, 3], [1000, 200, 3], [1000, 166, 3], [986, 172, 3]], '#ff5a2a'], [[[958, 84, 2], [988, 86, 2], [988, 76, 2], [958, 74, 2]], '#ff9a30'],\n    ],\n    wheels: [[210, 70], [774, 70]], beam: [44, 122],\n    glows: [['W', 40, 120, 0.032, 0.024, 0.85], ['O', 34, 72, 0.016, 0.014, 0.6], ['R', 994, 186, 0.04, 0.03, 0.9], ['O', 973, 80, 0.02, 0.014, 0.5]],\n  },\n  {\n    // BMW M3 E36 coupé : bouclier droit, capot plat et long, pare-brise très couché, vitres sans montant, malle courte\n    id: 'm3', name: 'M3 E36', len: 4433, width: 1710, ws: [340, 520], rw: [640, 815], paint: 'red', rim: 'mesh', caliper: '#c8a030', drop: 8,\n    profile: [\n      [18, 34, 6], [2, 50, 8], [0, 104, 6], [6, 112, 4], [12, 140, 6], [24, 150, 14], [200, 186, 90], [340, 213, 18], [520, 298, 60], [640, 300, 60],\n      [815, 232, 40], [975, 228, 10], [998, 220, 8], [1000, 190, 6], [999, 112, 8], [990, 54, 8], [972, 38, 6],\n    ],\n    sill: 36, arch: 12,\n    glass: [[[372, 210, 4], [512, 288, 24], [630, 292, 40], [776, 238, 12], [752, 222, 4]]],\n    dark: [[[4, 70, 2], [70, 72, 2], [70, 54, 2], [6, 52, 2]]],\n    mirror: [[372, 222, 4], [410, 230, 6], [414, 246, 6], [378, 242, 4]],\n    wing: [[930, 228, 3], [996, 236, 3], [998, 226, 3], [934, 222, 3]],\n    struts: [],\n    lamps: [\n      [[[2, 114, 2], [12, 116, 2], [14, 138, 2], [6, 136, 2]], '#fff4e8'], [[[284, 146, 3], [304, 147, 3], [304, 140, 3], [284, 139, 3]], '#ffa040'],\n      [[[8, 64, 2], [20, 66, 2], [20, 58, 2], [8, 56, 2]], '#fff0dc'], [[[962, 216, 3], [1000, 212, 3], [1000, 182, 3], [964, 186, 3]], '#ff2a1e'],\n    ],\n    wheels: [[179, 72], [790, 72]], beam: [10, 126],\n    glows: [['W', 8, 126, 0.035, 0.03, 0.85], ['O', 294, 143, 0.014, 0.012, 0.6], ['W', 14, 61, 0.02, 0.015, 0.5], ['R', 990, 198, 0.045, 0.034, 0.9]],\n  },\n];\n\nconst bbox = pts => pts.reduce((b, [x, y]) => [Math.min(b[0], x), Math.min(b[1], y), Math.max(b[2], x), Math.max(b[3], y)], [1e9, 1e9, -1e9, -1e9]);\n\n// arc de passage de roue, de droite à gauche par-dessus la roue, ouvert au niveau du bas de caisse\nfunction archPts(cu, cv, ra, yb, n) {\n  const a0 = Math.asin(Math.max(-1, Math.min(1, (yb - cv) / ra))), out = [];\n  for (let i = 0; i <= n; i++) { const a = a0 + (Math.PI - 2 * a0) * i / n; out.push([cu + ra * Math.cos(a), cv + ra * Math.sin(a)]); }\n  return out;\n}\n\n// complète une fiche décrite par son profil : caisse fermée et passages de roue circulaires\nfunction prepCar(def) {\n  if (def.body) return def;\n  const arch = ([cu, rad]) => archPts(cu, rad + 4, rad + def.arch, def.sill, 16);\n  const rA = arch(def.wheels[1]), fA = arch(def.wheels[0]);\n  def.body = def.profile.concat(rA, fA);\n  const well = a => [[a[0][0], 26]].concat(a, [[a[a.length - 1][0], 26]]);\n  def.archF = well(fA); def.archR = well(rA);\n  def.top = def.profile.slice(def.profile.findIndex(p => p[1] >= 70) - 1, def.profile.findIndex(p => p[0] >= 999) + 1);\n  return def;\n}\n\nfunction buildVignette() {\n  const c = mk(W, H), g = c.getContext('2d'), m = Math.max(W, H);\n  const gr = g.createRadialGradient(CX, H * 0.5, m * 0.32, CX, H * 0.5, m * 0.8);\n  gr.addColorStop(0, 'rgba(8,2,16,0)'); gr.addColorStop(1, 'rgba(8,2,16,0.55)');\n  g.fillStyle = gr; g.fillRect(0, 0, W, H);\n  return c;\n}\n\n/* ---------- particules ---------- */\n\nfunction softSprite(r, g, b, rim) {\n  const n = 96, c = mk(n, n), x = c.getContext('2d'), gr = x.createRadialGradient(n / 2, n / 2, 0, n / 2, n / 2, n / 2);\n  if (rim) {   // bokeh : disque presque uniforme au bord un peu plus lumineux\n    gr.addColorStop(0, `rgba(${r},${g},${b},0.35)`); gr.addColorStop(0.82, `rgba(${r},${g},${b},0.5)`);\n    gr.addColorStop(0.93, `rgba(${r},${g},${b},0.75)`); gr.addColorStop(1, `rgba(${r},${g},${b},0)`);\n  } else {\n    gr.addColorStop(0, `rgba(${r},${g},${b},0.9)`); gr.addColorStop(0.5, `rgba(${r},${g},${b},0.35)`); gr.addColorStop(1, `rgba(${r},${g},${b},0)`);\n  }\n  x.fillStyle = gr; x.fillRect(0, 0, n, n); return c;\n}\n\nfunction buildParticles() {\n  const r = rnd(61);\n  S.dust = Array.from({ length: Math.round(150 * W / (H * 1.78)) }, () => ({ x: r() * W, y: H * (0.12 + 0.62 * r()), z: r(), p: r() * 6.3, s: (0.8 + 2.2 * r() * r()) * U }));\n  S.bokeh = Array.from({ length: 5 }, () => ({ x: -r() * W * 2, y: H * (0.05 + 0.9 * r()), rad: H * (0.025 + 0.05 * r()), a: 0.05 + 0.07 * r(), v: 4.5 + 3 * r() }));\n  S.kick = []; S.kickAcc = 0;\n  S.dustSpr = softSprite(255, 214, 170); S.bokehSpr = softSprite(255, 190, 150, true); S.smokeSpr = softSprite(150, 104, 96);\n  S.shoot = { at: 6 + r() * 10, r };\n}\n\n// poussières en suspension, éclairées à contre-jour quand elles passent devant le soleil\nfunction drawDust(t, dt) {\n  const c = ctx, sx = CX, sy = H * Y.sun;\n  c.globalCompositeOperation = 'lighter';\n  for (const d of S.dust) {\n    d.x += lerp(0.9, 2.2, d.z) * H * dt;\n    if (d.x > W + 10) { d.x -= W + 20; d.y = H * (0.12 + 0.62 * Math.random()); }\n    const y = d.y + Math.sin(t * 0.6 + d.p) * H * 0.012;\n    const back = Math.max(0, 1 - Math.hypot(d.x - sx, y - sy) / (H * 0.55));\n    const a = (0.12 + 0.9 * back * back) * (0.6 + 0.4 * Math.sin(t * 1.7 + d.p * 3)) * (1 - WX.cur.rain) * (1 - 0.5 * WX.cur.fog) * (1 - 0.7 * WX.cur.over);\n    const rr = d.s * (1.5 + d.z * 2);\n    glow(S.dustSpr, d.x, y, rr, rr, a);\n  }\n  c.globalCompositeOperation = 'source-over'; c.globalAlpha = 1;\n}\n\n// grosses taches floues tout près de l'objectif, qui traversent l'image de temps en temps\nfunction drawBokeh(dt) {\n  const c = ctx;\n  c.globalCompositeOperation = 'lighter';\n  for (const b of S.bokeh) {\n    b.x += b.v * H * dt;\n    if (b.x - b.rad > W) { b.x = -b.rad - Math.random() * W * 2.5; b.y = H * (0.05 + 0.9 * Math.random()); }\n    if (b.x + b.rad > 0) glow(S.bokehSpr, b.x, b.y, b.rad, b.rad, b.a * (1 - 0.6 * WX.cur.rain));\n  }\n  c.globalCompositeOperation = 'source-over'; c.globalAlpha = 1;\n}\n\n// étoile filante, de loin en loin\nfunction drawShooting(t) {\n  const sh = S.shoot;\n  if (t < sh.at) return;\n  if (!sh.x) { const r = sh.r; sh.x = W * (0.1 + 0.8 * r()); sh.y = H * (0.03 + 0.18 * r()); sh.dx = (r() < 0.5 ? -1 : 1) * H * (0.5 + 0.3 * r()); sh.dy = H * (0.12 + 0.12 * r()); sh.t0 = t; }\n  const f = (t - sh.t0) / 0.9;\n  if (f >= 1) { sh.x = 0; sh.at = t + 14 + sh.r() * 26; return; }\n  const hx = sh.x + sh.dx * f, hy = sh.y + sh.dy * f, len = 0.22 * Math.min(1, f * 4);\n  const tx = hx - sh.dx * len, ty = hy - sh.dy * len, a = Math.sin(Math.PI * f);\n  const gr = ctx.createLinearGradient(tx, ty, hx, hy);\n  gr.addColorStop(0, 'rgba(255,240,230,0)'); gr.addColorStop(1, `rgba(255,248,240,${0.9 * a})`);\n  ctx.strokeStyle = gr; ctx.lineWidth = Math.max(1, 1.6 * U); ctx.lineCap = 'round';\n  ctx.beginPath(); ctx.moveTo(tx, ty); ctx.lineTo(hx, hy); ctx.stroke();\n}\n\n/* ---------- météo ---------- */\n// Chaque ambiance est un jeu de réglages ; l'ambiance courante glisse doucement vers la cible.\n// over : couverture nuageuse, rain : pluie, wet : route mouillée (sèche lentement), fog : brouillard,\n// storm : éclairs, wind : force du vent dans les palmiers.\n// Chaque ambiance a aussi sa palette, pour rester aussi colorée qu'au soleil, mais autrement :\n// grade : étalonnage [relevé des noirs r, g, b, gain r, g, b, saturation] ; sky : voile du ciel [haut, horizon, opacité] ;\n// cloud : teinte des nuages bas [haut, horizon] ; mist : brouillard [loin, près] ; lights : la ville s'allume davantage.\n// Nuageux : heure dorée sous un plafond violet. Pluie : nuit néon bleu et magenta. Orage : violet électrique.\n// Brouillard : pastel pêche et lavande.\nconst WEATHERS = [\n  { id: 'clear', name: 'Clear', over: 0, rain: 0, wet: 0, fog: 0, storm: 0, wind: 1, lights: 0,\n    grade: [0, 0, 0, 1, 1, 1, 1], sky: [[40, 24, 70], [255, 120, 60], 0], cloud: [[90, 70, 140], [255, 150, 90]], mist: [[176, 140, 170], [206, 156, 166]] },\n  { id: 'cloudy', name: 'Cloudy', over: 0.6, rain: 0, wet: 0, fog: 0.12, storm: 0, wind: 1.4, lights: 0.25,\n    grade: [0.012, 0, 0.02, 1.07, 0.98, 0.95, 1.14], sky: [[40, 24, 70], [255, 120, 60], 0.38], cloud: [[96, 74, 150], [255, 150, 90]], mist: [[200, 140, 140], [255, 170, 130]] },\n  { id: 'rain', name: 'Rain', over: 0.88, rain: 0.65, wet: 1, fog: 0.28, storm: 0, wind: 1.7, lights: 0.7,\n    grade: [0, 0.012, 0.035, 0.98, 1, 1.1, 1.32], sky: [[10, 20, 64], [210, 40, 130], 0.55], cloud: [[56, 76, 160], [255, 84, 170]], mist: [[60, 90, 160], [220, 90, 170]] },\n  { id: 'storm', name: 'Storm', over: 1, rain: 1, wet: 1, fog: 0.32, storm: 1, wind: 2.6, lights: 0.55,\n    grade: [0.02, 0, 0.05, 1.05, 0.92, 1.15, 1.36], sky: [[16, 8, 46], [120, 40, 170], 0.65], cloud: [[66, 44, 140], [210, 70, 210]], mist: [[70, 50, 140], [170, 80, 200]] },\n  { id: 'fog', name: 'Fog', over: 0.45, rain: 0, wet: 0.4, fog: 0.9, storm: 0, wind: 0.5, lights: 0.35,\n    grade: [0.03, 0.02, 0.03, 1.04, 1, 0.98, 1.12], sky: [[200, 170, 210], [255, 190, 160], 0.3], cloud: [[230, 200, 225], [255, 210, 180]], mist: [[214, 178, 210], [255, 196, 176]] },\n];\nconst deep = v => JSON.parse(JSON.stringify(v));\n// rapproche a de b, tableaux de nombres imbriqués\nfunction ease(a, b, k) { for (let i = 0; i < a.length; i++) { if (Array.isArray(a[i])) ease(a[i], b[i], k); else a[i] += (b[i] - a[i]) * k; } }\nconst css = (c, a) => `rgba(${c[0] | 0},${c[1] | 0},${c[2] | 0},${a})`;\n// enchaînement automatique, une étape toutes les deux à quatre minutes\nconst WEATHER_ROUTE = ['clear', 'cloudy', 'rain', 'storm', 'rain', 'cloudy', 'clear', 'fog', 'clear'];\n\nconst WX = (() => {\n  const fixed = WEATHERS.find(w => w.id === Q.get('weather')), cur = fixed || WEATHERS[0];\n  return { cur: deep(cur), target: cur, fixed: !!fixed, step: 0, next: 120 + Math.random() * 120, windT: 0 };\n})();\n\nfunction showLabel(text) { onLabel(text); }\n\nfunction setWeather(w, t) { WX.target = w; WX.next = t + 120 + Math.random() * 120; showLabel(w.name); }\n\nfunction stepWeather(t, dt) {\n  if (!WX.fixed && t > WX.next) { WX.step = (WX.step + 1) % WEATHER_ROUTE.length; setWeather(WEATHERS.find(w => w.id === WEATHER_ROUTE[WX.step]), t); }\n  const c = WX.cur, g = WX.target, k = Math.min(1, dt / 7);\n  for (const p of ['over', 'rain', 'fog', 'storm', 'wind', 'lights']) c[p] += (g[p] - c[p]) * k;\n  for (const p of ['grade', 'sky', 'cloud', 'mist']) ease(c[p], g[p], k);\n  // la route se mouille vite et sèche lentement\n  c.wet += (g.wet - c.wet) * Math.min(1, dt / (g.wet > c.wet ? 10 : 45));\n  WX.windT += dt * (0.6 + 0.4 * c.wind);\n}\n\n\n// couche de nuages bas et denses qui recouvre le ciel quand le temps se gâte, éclairée par en dessous près de l'horizon\nfunction buildOvercast() {\n  const TW = Math.ceil(Math.max(W, H * 1.78) * 1.6), CH = Math.ceil(H * Y.city), c = mk(TW, CH), g = c.getContext('2d');\n  const q = 3, w = Math.ceil(TW / q), h = Math.ceil(CH / q);\n  const d = fbm(47, w, h, Math.max(4, Math.round(TW / (H * 0.35))), Math.max(2, Math.round(CH / (H * 0.1))), 6);\n  const img = new ImageData(w, h), px = img.data, k = Math.max(1, Math.round(H * 0.015 / q));\n  // en gris : la teinte de l'ambiance est posée à l'affichage\n  const sh = [70, 70, 74], mid = [140, 138, 146], lit = [255, 255, 255];\n  for (let y = 0; y < h; y++) {\n    const fy = y / h, th = 0.34 + 0.1 * fy;\n    for (let x = 0; x < w; x++) {\n      const i = y * w + x, v = d[i], a = Math.min(1, Math.max(0, (v - th) / 0.12));\n      if (a <= 0) continue;\n      const below = y + k < h ? d[i + k * w] : 0, l = Math.min(1, Math.max(0, (v - below) * 7 + 0.1));\n      const col = mixc(mixc(sh, mid, l), lit, l * fy * 0.75);\n      px[i * 4] = col[0]; px[i * 4 + 1] = col[1]; px[i * 4 + 2] = col[2]; px[i * 4 + 3] = 255 * a * 0.97;\n    }\n  }\n  const lo = mk(w, h); lo.getContext('2d').putImageData(img, 0, 0);\n  g.imageSmoothingQuality = 'high'; g.drawImage(lo, 0, 0, w * q, h * q);\n  return { c, TW };\n}\n\n// tuile de pluie : traits obliques (la voiture file vers la gauche, la pluie semble partir vers la droite)\nfunction buildRainTile(T, n, len, wd, a) {\n  const c = mk(T, T), g = c.getContext('2d'), r = rnd(T + n);\n  g.lineCap = 'round'; g.lineWidth = wd;\n  for (let i = 0; i < n; i++) {\n    const x = r() * T, y = r() * T, l = len * (0.6 + 0.8 * r()), dx = l * 0.28;\n    g.strokeStyle = `rgba(215,222,255,${a * (0.35 + 0.65 * r())})`;\n    for (const [ox, oy] of [[0, 0], [-T, 0], [0, -T], [-T, -T]]) { g.beginPath(); g.moveTo(x + ox, y + oy); g.lineTo(x + ox + dx, y + oy + l); g.stroke(); }\n  }\n  return { c, T, pat: ctx.createPattern(c, 'repeat') };\n}\n\nfunction drawRain(tile, t, vy, alpha) {\n  if (alpha < 0.01) return;\n  const ox = (t * vy * 0.28 * H) % tile.T, oy = (t * vy * H) % tile.T;\n  ctx.save(); ctx.globalAlpha = alpha; ctx.translate(ox, oy); ctx.fillStyle = tile.pat; ctx.fillRect(-ox, -oy, W, H); ctx.restore();\n}\n\n// orage : éclairs espacés, parfois doublés, qui illuminent le ciel puis toute la scène\nfunction stepStorm(t, dt) {\n  const st = S.storm, k = WX.cur.storm;\n  st.flash = Math.max(0, st.flash - dt * 4);\n  if (st.bolt) { st.boltT -= dt; if (st.boltT <= 0) st.bolt = null; }\n  if (k < 0.3) return;\n  if (t > st.next) {\n    st.flash = 1; st.bolt = makeBolt(); st.boltT = 0.22;\n    st.again = Math.random() < 0.6 ? t + 0.09 + Math.random() * 0.1 : 0;\n    st.next = t + (3 + Math.random() * 10) / k;\n  }\n  if (st.again && t > st.again) { st.flash = Math.max(st.flash, 0.75); st.again = 0; }\n}\n\nfunction makeBolt() {\n  const r = Math.random, end = H * (Y.city - 0.12 - 0.1 * r());\n  const walk = (x, y, stop, sx) => { const p = [[x, y]]; while (y < stop) { y += H * (0.012 + 0.022 * r()); x += (r() - 0.5 + sx) * H * 0.045; p.push([x, y]); } return p; };\n  const main = walk(W * (0.08 + 0.84 * r()), H * 0.05, end, 0), branches = [];\n  for (let i = 0; i < 3; i++) { const [x, y] = main[1 + ((r() * (main.length - 2)) | 0)]; branches.push(walk(x, y, y + H * (0.04 + 0.08 * r()), r() < 0.5 ? -0.4 : 0.4)); }\n  return [main, ...branches];\n}\n\nfunction drawStorm() {\n  const st = S.storm, c = ctx;\n  c.globalCompositeOperation = 'lighter';\n  if (st.flash > 0) { c.fillStyle = `rgba(190,190,255,${st.flash * 0.45})`; c.fillRect(0, 0, W, H * Y.city); }\n  if (st.bolt) {\n    const a = Math.min(1, st.boltT / 0.1);\n    st.bolt.forEach((pts, i) => {\n      for (const [col, lw] of [[`rgba(170,160,255,${0.35 * a})`, 8], [`rgba(255,255,255,${0.95 * a})`, i ? 1.2 : 2.2]]) {\n        c.strokeStyle = col; c.lineWidth = lw * U; c.lineJoin = 'round';\n        c.beginPath(); pts.forEach(([x, y], k) => k ? c.lineTo(x, y) : c.moveTo(x, y)); c.stroke();\n      }\n    });\n  }\n  c.globalCompositeOperation = 'source-over';\n}\n\n// brouillard : un voile rose-gris, plus épais vers l'horizon\nfunction drawFog(y1, a) {\n  if (a < 0.005) return;\n  const gr = ctx.createLinearGradient(0, 0, 0, y1);\n  const [far, near] = WX.cur.mist;\n  gr.addColorStop(0, css(far, a * 0.35)); gr.addColorStop(1, css(near, a));\n  ctx.fillStyle = gr; ctx.fillRect(0, 0, W, y1);\n}\n\n/* ---------- vue de trois quarts face, en perspective ---------- */\n// Repère du monde en mètres : x le long de la route (la voiture roule vers -x), y vers le haut, z en travers.\n// La caméra est devant la voiture, un peu sur sa droite et en hauteur ; la baie, les palmiers et la ville sont\n// de l'autre côté de la route, derrière la voiture, sous le soleil couchant.\nconst CAMERA = { pos: [-5.9, 1.75, 4.5], at: [0.5, 0.45, -0.6], focal: 1.5, car: [0.5, 0.64] };\nconst ROAD = { near: 3.8, far: -5.8, kerb: -6.25, rail: -6.4, lamp: -7.1, palm: -8.8, divider: -1.9, speed: 24 };\nlet CAM = null;\n\nfunction setupCamera() {\n  const nrm = v => { const l = Math.hypot(v[0], v[1], v[2]); return v.map(x => x / l); };\n  const [px, py, pz] = CAMERA.pos, [ax, ay, az] = CAMERA.at;\n  const F = nrm([ax - px, ay - py, az - pz]), R = nrm([-F[2], 0, F[0]]);\n  const Up = [R[1] * F[2] - R[2] * F[1], R[2] * F[0] - R[0] * F[2], R[0] * F[1] - R[1] * F[0]];\n  CAM = { P: [px, py, pz], F, R, U: Up, f: CAMERA.focal * H, sx: 0, sy: 0 };\n  // décalage d'objectif : la voiture tombe au tiers bas de l'image, comme sur le fond d'écran d'origine\n  const c = proj3(0, 0.6, 0);\n  CAM.sx = W * CAMERA.car[0] - c[0]; CAM.sy = H * CAMERA.car[1] - c[1];\n  const hz = proj3(px + F[0] * 1e5, 0, pz + F[2] * 1e5);\n  CAM.horizon = hz[1] / H; CAM.sunX = hz[0];\n  CAM.ref = c[2];\n}\nfunction toCam(x, y, z) {\n  const d0 = x - CAM.P[0], d1 = y - CAM.P[1], d2 = z - CAM.P[2];\n  return [d0 * CAM.R[0] + d1 * CAM.R[1] + d2 * CAM.R[2], d0 * CAM.U[0] + d1 * CAM.U[1] + d2 * CAM.U[2], d0 * CAM.F[0] + d1 * CAM.F[1] + d2 * CAM.F[2]];\n}\nconst camToScreen = (q) => [W / 2 + CAM.sx + CAM.f * q[0] / q[2], H / 2 + CAM.sy - CAM.f * q[1] / q[2], q[2]];\nconst proj3 = (x, y, z) => camToScreen(toCam(x, y, z));\n\n// polygone du monde : découpé au plan proche de la caméra puis tracé à l'écran ; faux s'il est entièrement derrière\nfunction path3(pts) {\n  const near = 0.5, q = pts.map(p => toCam(p[0], p[1], p[2])), out = [];\n  for (let i = 0; i < q.length; i++) {\n    const a = q[i], b = q[(i + 1) % q.length];\n    if (a[2] >= near) out.push(a);\n    if ((a[2] >= near) !== (b[2] >= near)) { const t = (near - a[2]) / (b[2] - a[2]); out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, near]); }\n  }\n  if (out.length < 3) return false;\n  ctx.beginPath();\n  out.forEach((p, i) => { const s = camToScreen(p); if (i) ctx.lineTo(s[0], s[1]); else ctx.moveTo(s[0], s[1]); });\n  ctx.closePath();\n  return true;\n}\nconst quadX = (x0, x1, y0, y1, z0, z1) => [[x0, y0, z0], [x1, y0, z0], [x1, y1, z1], [x0, y1, z1]];   // bande le long de la route\n// une tache au sol (ombre, flaque de phare) : le sprite circulaire est plaqué sur le plan de la route\nfunction groundSprite(spr, x, z, rx, rz, a) {\n  const c = proj3(x, 0.01, z), px = proj3(x + rx, 0.01, z), pz = proj3(x, 0.01, z + rz);\n  if (c[2] < 0.6 || px[2] < 0.6 || pz[2] < 0.6) return;\n  ctx.save(); ctx.globalAlpha = a;\n  ctx.setTransform(px[0] - c[0], px[1] - c[1], pz[0] - c[0], pz[1] - c[1], c[0], c[1]);\n  ctx.drawImage(spr, -1, -1, 2, 2);\n  ctx.restore();\n}\n\n/* décor qui défile : palmiers et lampadaires de l'autre côté de la glissière */\nfunction buildScenery() {\n  const r = rnd(41), palms = [], lamps = [], sprites = [];\n  for (let i = 0; i < 6; i++) sprites.push(buildPalm(200 + i, H * 0.6, 0, 0, 0));\n  for (let x = -40; x < 260; x += 7 + r() * 9) palms.push({ x, z: ROAD.palm - r() * 2.2, h: 8.5 + r() * 3.5, spr: sprites[(r() * 6) | 0], ph: r() * 6.3, flip: r() < 0.5 ? -1 : 1 });\n  for (let x = -40; x < 260; x += 32) lamps.push({ x });\n  return { palms, lamps, sprites, span: 300, sh: H * 0.6, shadowSpr: shadowSprite() };\n}\nfunction shadowSprite() {\n  const n = 128, c = mk(n, n), g = c.getContext('2d'), gr = g.createRadialGradient(n / 2, n / 2, 0, n / 2, n / 2, n / 2);\n  gr.addColorStop(0, 'rgba(6,2,8,0.9)'); gr.addColorStop(0.55, 'rgba(6,2,8,0.6)'); gr.addColorStop(1, 'rgba(6,2,8,0)');\n  g.fillStyle = gr; g.fillRect(0, 0, n, n); return c;\n}\nfunction stepScenery(dt) {\n  const sc = S.scn, d = ROAD.speed * dt;\n  for (const p of sc.palms) { p.x += d; if (p.x > 260) p.x -= sc.span; }\n  for (const l of sc.lamps) { l.x += d; if (l.x > 260) l.x -= sc.span; }\n  sc.dash = ((sc.dash || 0) + d) % 12; sc.post = ((sc.post || 0) + d) % 2.6;\n}\n\n// palmiers et lampadaires, du plus lointain au plus proche\nfunction drawScenery(t, wx) {\n  const sc = S.scn, items = [];\n  for (const p of sc.palms) { const q = toCam(p.x, 0, p.z); if (q[2] > 1) items.push([q[2], 0, p]); }\n  for (const l of sc.lamps) { const q = toCam(l.x, 0, ROAD.lamp); if (q[2] > 1) items.push([q[2], 1, l]); }\n  items.sort((a, b) => b[0] - a[0]);\n  const c = ctx, sway = 0.012 * wx.wind;\n  for (const [zc, kind, o] of items) {\n    if (kind === 0) {\n      const b = proj3(o.x, 0, o.z), k = o.h * CAM.f / zc / sc.sh, sp = o.spr;\n      if (b[0] < -sp.c.width * k || b[0] > W + sp.c.width * k) continue;\n      const sh = (Math.sin(WX.windT * 0.9 + o.ph) + 0.35 * Math.sin(WX.windT * 2.3 + o.ph * 1.7)) * sway;\n      c.setTransform(o.flip * k, 0, sh * k, k, b[0], b[1]);\n      c.drawImage(sp.c, -sp.ax, -sp.ay);\n      c.setTransform(1, 0, 0, 1, 0, 0);\n    } else {\n      // lampadaire : mât, crosse tournée vers la route, lanterne\n      const z = ROAD.lamp, base = proj3(o.x, 0, z), top = proj3(o.x, 8.6, z), head = proj3(o.x, 8.7, z + 1.9);\n      if (base[0] < -W * 0.2 || base[0] > W * 1.2) continue;\n      c.strokeStyle = '#1e1420'; c.lineCap = 'round';\n      c.lineWidth = Math.max(1, 0.2 * CAM.f / zc);\n      c.beginPath(); c.moveTo(base[0], base[1]); c.lineTo(top[0], top[1]); c.quadraticCurveTo(lerp(top[0], head[0], 0.2), head[1] - 0.15 * CAM.f / zc, head[0], head[1]); c.stroke();\n      o.head = head;\n    }\n  }\n}\nfunction drawLampGlows(wx, halo) {\n  ctx.globalCompositeOperation = 'lighter';\n  for (const l of S.scn.lamps) {\n    const h = l.head; if (!h || h[2] < 1 || h[0] < -W * 0.3 || h[0] > W * 1.3) continue;\n    const k = CAM.f / h[2];\n    glow(S.glowO, h[0], h[1], 3.6 * k * halo, 3.6 * k * halo, 0.4 + 0.15 * wx.fog);\n    glow(S.glowW, h[0], h[1], 1.1 * k * halo, 1.1 * k * halo, 0.95);\n  }\n  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;\n}\n\n// glissière, mur, bordure éclairée, route et marquages\nfunction drawRoad(t, wx) {\n  const c = ctx, X0 = -60, X1 = 420, sc = S.scn;\n  // mur et bordure de l'autre côté\n  if (path3(quadX(X0, X1, 0, 0.62, ROAD.rail - 0.15, ROAD.rail - 0.15))) {\n    const g = c.createLinearGradient(0, H * CAM.horizon, 0, H); g.addColorStop(0, '#4e2626'); g.addColorStop(1, '#2c1416');\n    c.fillStyle = g; c.fill();\n  }\n  // poteaux de glissière qui défilent\n  c.fillStyle = '#24100f';\n  for (let x = -20 - sc.post; x < 260; x += 2.6) {\n    const q = toCam(x, 0, ROAD.rail); if (q[2] < 1) continue;\n    if (path3([[x, 0.55, ROAD.rail], [x + 0.1, 0.55, ROAD.rail], [x + 0.1, 1.05, ROAD.rail], [x, 1.05, ROAD.rail]])) c.fill();\n  }\n  // deux lisses\n  for (const y of [0.78, 1.02]) if (path3(quadX(X0, X1, y, y + 0.1, ROAD.rail, ROAD.rail))) {\n    const g = c.createLinearGradient(0, H * CAM.horizon - H * 0.02, 0, H * 0.75); g.addColorStop(0, '#c89088'); g.addColorStop(0.4, '#6a3a3a'); g.addColorStop(1, '#2a1214');\n    c.fillStyle = g; c.fill();\n  }\n  // trottoir de l'autre côté, sa bordure attrape le soleil\n  if (path3([[X0, 0.02, ROAD.far], [X1, 0.02, ROAD.far], [X1, 0.02, ROAD.kerb], [X0, 0.02, ROAD.kerb]])) { c.fillStyle = '#f08038'; c.fill(); }\n  // chaussée\n  if (path3([[X0, 0, ROAD.near], [X1, 0, ROAD.near], [X1, 0, ROAD.far], [X0, 0, ROAD.far]])) {\n    const g = c.createLinearGradient(0, H * CAM.horizon, 0, H);\n    g.addColorStop(0, '#5a2a28'); g.addColorStop(0.25, '#3c1a1a'); g.addColorStop(1, '#22120f');\n    c.fillStyle = g; c.fill();\n  }\n  // côté caméra : bas-côté sombre\n  if (path3([[X0, 0, ROAD.near], [X1, 0, ROAD.near], [X1, 0, ROAD.near + 6], [X0, 0, ROAD.near + 6]])) { c.fillStyle = '#1a0d0c'; c.fill(); }\n  // lignes de rive continues et ligne de séparation en pointillés\n  c.fillStyle = 'rgba(255,226,222,0.85)';\n  for (const z of [ROAD.far + 0.25, ROAD.near - 0.25]) if (path3(quadX(X0, X1, 0.01, 0.01, z - 0.07, z + 0.07))) c.fill();\n  for (let x = -24 - (12 - sc.dash); x < 300; x += 12) if (path3(quadX(x, x + 3, 0.01, 0.01, ROAD.divider - 0.07, ROAD.divider + 0.07))) c.fill();\n}\n\n/* ---------- voitures en volume (WebGL) ---------- */\n// La caisse est un « loft » : tranche après tranche le long de la voiture, une section arrondie suit le profil\n// (bas de caisse, ceinture, pavillon), la largeur se resserre au nez et à la poupe, la ceinture rentre en haut\n// (custode et pavillon plus étroits). La peinture vernie reflète un ciel de couchant : c'est elle qui donne le volume.\n\nconst CAR_VS = `\nattribute vec3 aP, aN, aM, aL;\nuniform vec3 uOff, uScl, uCam, uR, uU, uF, uView;\nuniform vec2 uShift;\nvarying vec3 vP, vN, vM, vL, vLoc;\nvoid main() {\n  vec3 p = aP * uScl + uOff; vP = p; vN = aN * sign(uScl); vM = aM; vL = aL; vLoc = aP;\n  vec3 d = p - uCam; float xc = dot(d, uR), yc = dot(d, uU), zc = dot(d, uF);\n  float sx = uView.y * 0.5 + uShift.x + uView.x * xc / zc, sy = uView.z * 0.5 + uShift.y - uView.x * yc / zc;\n  gl_Position = vec4((sx / uView.y * 2.0 - 1.0) * zc, (1.0 - sy / uView.z * 2.0) * zc, ((zc - 0.4) / 90.0 * 2.0 - 1.0) * zc, zc);\n}`;\nconst CAR_FS = `\nprecision highp float;\nvarying vec3 vP, vN, vM, vL, vLoc;\nuniform vec3 uCam, uSun, uPaint, uSkyTop, uSkyHor, uGround, uCaliper;\nuniform float uSunK, uKind, uSpin, uRim, uRad, uClear;\nvec3 env(vec3 r) {\n  float h = r.y, sd = max(dot(r, uSun), 0.0);\n  vec3 sky = mix(uSkyHor, uSkyTop, smoothstep(0.0, 0.45, h));\n  sky += vec3(1.0, 0.72, 0.48) * (pow(sd, 10.0) * 0.7 + pow(sd, 260.0) * 6.0) * uSunK;\n  vec3 gnd = uGround * (0.55 + 0.45 * smoothstep(-0.35, 0.0, h));\n  gnd += vec3(1.0, 0.5, 0.2) * 0.6 * exp(-pow((h + 0.03) / 0.012, 2.0));\n  return mix(gnd, sky, smoothstep(-0.003, 0.003, h));\n}\nvoid main() {\n  vec3 V = normalize(uCam - vP), N = normalize(vN);\n  bool inside = dot(N, V) < -0.2;          // on voit l'envers de la tôle : intérieur des passages de roue, dessous\n  if (dot(N, V) < 0.0) N = normalize(N - V * dot(N, V) * 1.01);\n  vec3 R = reflect(-V, N);\n  float ndv = clamp(dot(N, V), 0.0, 1.0), fr = pow(1.0 - ndv, 5.0);\n  vec3 hemi = mix(uGround * 0.9, uSkyTop * 1.1, N.y * 0.5 + 0.5);\n  float fill = max(dot(N, normalize(vec3(-0.75, 0.5, 0.45))), 0.0), sunD = max(dot(N, uSun), 0.0) * uSunK;\n  vec3 light = hemi * 0.5 + vec3(1.0, 0.84, 0.74) * fill * 0.32 + vec3(1.0, 0.62, 0.42) * sunD;\n  vec3 col;\n  if (uKind < 0.5) {\n    if (vM.x > 0.5) {\n      col = vec3(0.012, 0.016, 0.034) + env(R) * (0.1 + 0.9 * fr);\n    } else {\n      vec3 base = mix(uPaint, vec3(0.018, 0.016, 0.02), vM.y);\n      col = base * light + env(R) * (0.07 + 0.93 * fr) * uClear * (1.0 - 0.7 * vM.y);\n      col += vec3(1.0, 0.55, 0.35) * pow(1.0 - ndv, 3.0) * 0.18 * uSunK;\n    }\n    if (vM.z > 0.5) col = vL * 1.5;\n    if (inside) col = vec3(0.012, 0.009, 0.012);\n  } else if (uKind < 1.5) {\n    col = vec3(0.03, 0.026, 0.03) * light * 1.6 + env(R) * 0.05 * fr;\n  } else {\n    float r = length(vLoc.xy) / uRad, rr = r / 0.72;\n    if (rr > 1.0) col = vec3(0.03, 0.026, 0.03) * light * 1.6;\n    else {\n      float a = atan(vLoc.y, vLoc.x) + uSpin, m = 0.0;\n      if (uRim < 0.5) {\n        float k = fract(a * 5.0 / 6.28318) - 0.5; float d = length(vec2(rr - 0.58, k * 1.25 * 0.58));\n        m = smoothstep(0.17, 0.23, d);\n      } else if (uRim < 1.5) {\n        float k = abs(fract(a * 5.0 / 6.28318) - 0.5); m = 1.0 - smoothstep(0.06, 0.12, k - (1.0 - rr) * 0.04);\n      } else {\n        float k = abs(fract(a * 10.0 / 6.28318) - 0.5); m = 1.0 - smoothstep(0.05, 0.1, k);\n        m = max(m, 1.0 - smoothstep(0.015, 0.04, abs(rr - 0.32)));\n      }\n      m = max(m, max(1.0 - smoothstep(0.2, 0.26, rr), smoothstep(0.86, 0.9, rr)));\n      vec3 metal = vec3(0.6, 0.57, 0.6) * light * 0.7 + env(R) * 0.55;\n      float a0 = atan(vLoc.y, vLoc.x);\n      vec3 inner = (rr > 0.45 && rr < 0.84 && a0 > 0.5 && a0 < 1.5) ? uCaliper * light : vec3(0.05, 0.045, 0.05) * light;\n      col = mix(inner, metal, m);\n    }\n  }\n  gl_FragColor = vec4(col, 1.0);\n}`;\n\nfunction envelope(pts, u, top) {\n  let best = top ? -1e9 : 1e9, hit = false;\n  for (let i = 0; i < pts.length; i++) {\n    const a = pts[i], b = pts[(i + 1) % pts.length];\n    if ((a[0] - u) * (b[0] - u) > 0 || a[0] === b[0]) continue;\n    const y = a[1] + (b[1] - a[1]) * (u - a[0]) / (b[0] - a[0]); hit = true;\n    best = top ? Math.max(best, y) : Math.min(best, y);\n  }\n  return hit ? best : null;\n}\nfunction inPoly(pts, u, y) {\n  let inside = false;\n  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {\n    const [xi, yi] = pts[i], [xj, yj] = pts[j];\n    if ((yi > y) !== (yj > y) && u < (xj - xi) * (y - yi) / (yj - yi) + xi) inside = !inside;\n  }\n  return inside;\n}\nconst sstep = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };\nconst hexf = h => { const n = parseInt(h.slice(1), 16); return [(n >> 16 & 255) / 255, (n >> 8 & 255) / 255, (n & 255) / 255]; };\n\n// normales lissées par sommet, tournées vers l'extérieur (le haut de la caisse doit regarder vers le ciel)\nfunction smoothNormals(P, Nn, idx) {\n  for (let i = 0; i < idx.length; i += 3) {\n    const a = idx[i] * 3, b = idx[i + 1] * 3, c2 = idx[i + 2] * 3;\n    const e1 = [P[b] - P[a], P[b + 1] - P[a + 1], P[b + 2] - P[a + 2]], e2 = [P[c2] - P[a], P[c2 + 1] - P[a + 1], P[c2 + 2] - P[a + 2]];\n    const n = [e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2],